/* ============================================================================
   GRADING ENGINE — pure, independently-testable calculation functions.
   Nothing here touches the DOM or IndexedDB directly.
   ============================================================================ */
const GradingEngine = {
  /** Resolve which versioned policy applies for a given school year. */
  resolvePolicy(context = {}) {
    const sy = context.schoolYear || (typeof State !== 'undefined' ? State.schoolYear : null) || CONFIG.DEFAULT_SCHOOL_YEAR;
    if (sy >= '2027-2028') return GRADING_POLICIES['ZERO-BASED-2027'];
    if (sy >= '2026-2027') return GRADING_POLICIES['DO015-2026'];
    return GRADING_POLICIES['LEGACY-DO8-2015'];
  },
    /** In-memory cache of policy-level overrides, loaded from IndexedDB at boot.
   *  Shape: { [policyVersion]: { weights?, transmutation? } } */
  _overrides: {},

  /** Load overrides from DB. Called once during App.loadState(). */
  async loadOverrides() {
    try {
      const saved = await DB.getSetting('gradingPolicyOverrides', {});
      this._overrides = (saved && typeof saved === 'object') ? saved : {};
    } catch (e) {
      console.warn('[GradingEngine] Could not load overrides:', e);
      this._overrides = {};
    }
  },

  /** Save / clear an override for one policy version. Pass null to clear. */
  async saveOverride(policyVersion, override) {
    if (!this._overrides) this._overrides = {};
    if (override) {
      this._overrides[policyVersion] = override;
    } else {
      delete this._overrides[policyVersion];
    }
    try {
      await DB.setSetting('gradingPolicyOverrides', this._overrides);
    } catch (e) {
      console.warn('[GradingEngine] Could not persist override:', e);
    }
  },

  /** Returns true if this policy has any active override. */
  hasOverride(policyVersion) {
    return !!(this._overrides && this._overrides[policyVersion]);
  },

  /** Existing resolvePolicy — MODIFY the return value to merge overrides. */
  resolvePolicy(context = {}) {
    const sy = context.schoolYear
      || (typeof State !== 'undefined' ? State.schoolYear : null)
      || CONFIG.DEFAULT_SCHOOL_YEAR;
    let base;
    if (sy >= '2027-2028')      base = GRADING_POLICIES['ZERO-BASED-2027'];
    else if (sy >= '2026-2027') base = GRADING_POLICIES['DO015-2026'];
    else                        base = GRADING_POLICIES['LEGACY-DO8-2015'];

    const override = this._overrides && this._overrides[base.version];
    if (!override) return base;

    // Shallow-clone so we never mutate the master GRADING_POLICIES object
    const merged = Object.assign({}, base);

    // Merge weight overrides key by key
    if (override.weights && typeof override.weights === 'object') {
      merged.weights = Object.assign({}, base.weights || {});
      Object.keys(override.weights).forEach(key => {
        if (override.weights[key]) {
          merged.weights[key] = Object.assign({}, override.weights[key]);
        }
      });
    }

    // Replace the transmutation table or disable it entirely
    if (override.transmutation === null) {
      merged.transmutation = null;
    } else if (override.transmutation && typeof override.transmutation === 'object') {
      merged.transmutation = {
        version: (base.transmutation && base.transmutation.version || base.version) + '-OVERRIDE',
        label:   override.transmutation.label || 'Custom Transmutation Table',
        table:   Array.isArray(override.transmutation.table)
                   ? override.transmutation.table.map(b => ({ min: +b.min, max: +b.max, reported: +b.reported }))
                   : (base.transmutation ? base.transmutation.table : [])
      };
    }

    return merged;
  },

  /** Determine which key-stage/subject weight key applies. */
  resolveWeightKey(gradeLevel, subject, subjectClassification) {
    const g = (gradeLevel || '').toLowerCase();
    const subj = (subject || '').toLowerCase();
    const isSkillSubject = /\bepp\b|\btle\b|\bmapeh\b|technology and livelihood|music|arts\b|physical education|\bpe\b|health\b/.test(subj);
    if (/kindergarten|grade 1\b|grade 2\b|grade 3\b/.test(g)) {
      return isSkillSubject ? 'KS1_SKILL' : 'KS1_CORE';
    }
    if (/grade 4|grade 5|grade 6/.test(g)) {
      return isSkillSubject ? 'KS2_EPP_TLE_MAPEH' : 'KS2_CORE';
    }
    if (/grade 7|grade 8|grade 9|grade 10/.test(g)) {
      return isSkillSubject ? 'KS3_EPP_TLE_MAPEH' : 'KS3_CORE';
    }
    if (/grade 11|grade 12/.test(g)) {
      switch (subjectClassification) {
        case 'Academic Elective': return 'KS4_SHS_ACADEMIC';
        case 'Field Exposure / Apprenticeship': return 'KS4_SHS_FIELD';
        case 'Arts / Creative Production': return 'KS4_SHS_ARTS';
        case 'Research / Design & Innovation': return 'KS4_SHS_RESEARCH';
        case 'TechPro Elective': return 'KS4_SHS_TECHPRO';
        case 'Work Immersion': return 'KS4_SHS_WORK_IMMERSION';
        default: return 'KS4_SHS_CORE';
      }
    }
    return 'KS2_CORE';
  },
  calculatePercentageScore(raw, highest) {
    const r = Number(raw), h = Number(highest);
    if (!h || isNaN(r) || isNaN(h) || h <= 0) return 0;
    return Utils.round((r / h) * 100, 2);
  },
  calculateWeightedScore(pct, weightPct) {
    const p = Number(pct) || 0, w = Number(weightPct) || 0;
    return Utils.round(p * (w / 100), 2);
  },
  /** Combine ST1/ST2/TE percentages into a single Examinations percentage. */
  calculateExaminationComponent(st1Pct, st2Pct, tePct, substructure) {
    const sub = substructure || { ST1: 30, ST2: 30, TE: 40 };
    const s1 = Number(st1Pct) || 0, s2 = Number(st2Pct) || 0, te = Number(tePct) || 0;
    return Utils.round(s1 * (sub.ST1/100) + s2 * (sub.ST2/100) + te * (sub.TE/100), 2);
  },
  /** components = { wwPct, ptPct, exPct }; weights = { WW, PT, EX } */
  calculateInitialGrade(components, weights) {
    const ww = GradingEngine.calculateWeightedScore(components.wwPct, weights.WW);
    const pt = GradingEngine.calculateWeightedScore(components.ptPct, weights.PT);
    const ex = GradingEngine.calculateWeightedScore(components.exPct, weights.EX);
    return Utils.round(ww + pt + ex, 2);
  },
  /** Returns { initialGrade, reportedGrade, transmutationPolicy } — never overwrites initialGrade. */
  applyTransmutation(initialGrade, policy) {
    const ig = Number(initialGrade) || 0;
    if (!policy || !policy.transmutation) {
      return { initialGrade: ig, reportedGrade: Math.round(ig), transmutationPolicy: null };
    }
    const table = policy.transmutation.table;
    for (const band of table) {
      if (ig >= band.min && ig <= band.max) {
        return { initialGrade: ig, reportedGrade: band.reported, transmutationPolicy: policy.transmutation.version };
      }
    }
    const sorted = table.slice().sort((a,b) => a.min - b.min);
    if (ig < sorted[0].min) return { initialGrade: ig, reportedGrade: sorted[0].reported, transmutationPolicy: policy.transmutation.version };
    const top = sorted[sorted.length-1];
    return { initialGrade: ig, reportedGrade: top.reported, transmutationPolicy: policy.transmutation.version };
  },
  getDescriptor(reportedGrade, policy) {
    const g = Number(reportedGrade);
    const list = (policy && policy.descriptors) || GRADING_POLICIES['DO015-2026'].descriptors;
    if (reportedGrade === '' || reportedGrade === null || reportedGrade === undefined || isNaN(g)) {
      return { label: '—', description: '' };
    }
    for (const d of list) if (g >= d.min && g <= d.max) return d;
    return list[list.length - 1];
  },
  /** termGrades: array of finalized/live reported grades for the terms that have data. */
  calculateFinalGrade(termGrades) {
    const nums = (termGrades || []).map(Number).filter(n => !isNaN(n) && n > 0);
    if (!nums.length) return null;
    return Math.round(Utils.avg(nums));
  },
  /** finalGrades: this learner's Final Grade in each learning area/class. Best-effort —
      KlazAssist tracks one class at a time, so this only covers classes recorded in this app. */
  calculateGeneralAverage(finalGrades) {
    const nums = (finalGrades || []).map(Number).filter(n => !isNaN(n) && n > 0);
    if (!nums.length) return null;
    return Utils.round(Utils.avg(nums), 2);
  },
  /** SF9 — Final Grade per learning area = average of the three term grades.
   *  Returns null until all terms have a grade, so partial data never
   *  produces a misleading final. */
  calculateSubjectFinal(term1, term2, term3) {
    const nums = [term1, term2, term3].map(Number).filter(n => !isNaN(n) && n > 0);
    if (nums.length < 3) return null;
    return Math.round(nums.reduce((a, b) => a + b, 0) / 3);
  },

  /** SF9 — General Weighted Average = mean of all subject Final Grades. */
  calculateGeneralAverageFromFinals(subjectFinals) {
    const finals = (subjectFinals || [])
      .map(Number)
      .filter(n => !isNaN(n) && n > 0);
    if (!finals.length) return null;
    return Math.round(finals.reduce((a, b) => a + b, 0) / finals.length);
  },

  /** SF9 — Passed if Final Grade >= passing threshold, else Failed. */
  getSubjectRemarks(finalGrade, passingGrade = 75) {
    if (finalGrade === null || finalGrade === undefined || isNaN(finalGrade)) return '';
    return Number(finalGrade) >= Number(passingGrade) ? 'Passed' : 'Failed';
  },

};

/* Thin wrapper matching the brief's requested API shape. */
const TransmutationEngine = {
  getTable({ schoolYear, policyVersion } = {}) {
    const policy = policyVersion ? GRADING_POLICIES[policyVersion] : GradingEngine.resolvePolicy({ schoolYear });
    return policy ? policy.transmutation : null;
  },
  transmute(initialGrade, { schoolYear, policyVersion } = {}) {
    const policy = policyVersion ? GRADING_POLICIES[policyVersion] : GradingEngine.resolvePolicy({ schoolYear });
    return GradingEngine.applyTransmutation(initialGrade, policy);
  }
};

/* ============================================================================
   ATTENDANCE POLICY — maps KlazAssist's internal attendance statuses to the
   codes shown on the printed SF2. Configurable in one place; NOT independently
   verified against a live official SF2 instruction sheet — check with your
   Division before relying on it for submission.
   ============================================================================ */
const AttendancePolicy = {
  // Common DepEd SF2 convention: blank = present; only exceptions are marked.
  codes: { Present: '', Absent: 'A', Late: 'L', Excused: 'E' }
};

/* ============================================================================
   MERGE ENGINE — non-destructive import
   ──────────────────────────────────────────────────────────────────────────
   Merges a KlazAssist backup into the live database without wiping.

   Rules of engagement:
     • Records that exist only in the backup → INSERT
     • Records that exist on both sides → the newer one wins
        · primary signal:  updatedAt
        · fallback:        createdAt
        · neither usable:  keep local (conservative)
     • Records that exist only locally → UNTOUCHED (never deleted)
     • Finalized termGrades that differ on both sides → CONFLICT
     • Learners with the same LRN but different IDs → CONFLICT
     • The `settings` store is SKIPPED entirely — it holds credentials,
       API keys, and device-local UI state that must never travel.
   ============================================================================ */
const MergeEngine = {
  SKIP_STORES: new Set(['settings']),

  // Stores where a mismatch between two records has no safe automatic
  // answer. A predicate returns true when the pair should be reported
  // as a conflict rather than resolved silently.
  CONFLICT_RULES: {
    termGrades: (local, remote) =>
      local.status   === 'finalized' &&
      remote.status  === 'finalized' &&
      (local.reportedGrade !== remote.reportedGrade ||
       local.initialGrade  !== remote.initialGrade  ||
       local.finalizedAt   !== remote.finalizedAt)
  },

  // Fields that should be preserved from local when applying a remote
  // update whose value for that field is empty. Prevents a stale backup
  // from blanking out a locally-captured learner photo.
  PRESERVE_IF_REMOTE_EMPTY: {
    learners: ['photo']
  },

  /* ---- Compare two records; decide the winner. ---- */
  _compare(local, remote, store) {
    const rule = this.CONFLICT_RULES[store];
    if (rule && rule(local, remote)) {
      return { winner: 'conflict', reason: 'Both copies are finalized and differ' };
    }

    // 1. Prefer updatedAt when both sides have it
    if (local.updatedAt && remote.updatedAt) {
      if (local.updatedAt > remote.updatedAt)  return { winner: 'local',  reason: 'Local is newer' };
      if (remote.updatedAt > local.updatedAt)  return { winner: 'remote', reason: 'Backup is newer' };
    }

    // 2. Fall back to createdAt
    if (local.createdAt && remote.createdAt) {
      if (local.createdAt > remote.createdAt)  return { winner: 'local',  reason: 'Local created later' };
      if (remote.createdAt > local.createdAt)  return { winner: 'remote', reason: 'Backup created later' };
    }

    // 3. If neither timestamp is usable, deep-compare
    if (this._recordsEqual(local, remote)) return { winner: 'equal', reason: '' };

    // 4. Cannot decide — keep local
    return { winner: 'local', reason: 'No comparable timestamps — keeping local' };
  },

  _recordsEqual(a, b) {
    try { return JSON.stringify(a) === JSON.stringify(b); }
    catch (e) { return false; }
  },

  /* ---- Build a merge plan from a parsed backup. Pure; no writes. ---- */
  async buildPlan(snapshot) {
    if (!snapshot || !snapshot.data) throw new Error('Invalid snapshot.');

    const plan = {
      inserts: [], updates: [], conflicts: [], skips: [],
      stats: { perStore: {} }
    };

    for (const store of CONFIG.STORES) {
      if (this.SKIP_STORES.has(store)) continue;

      const remoteRecords = Array.isArray(snapshot.data[store]) ? snapshot.data[store] : [];
      let localRecords = [];
      try { localRecords = await DB.getAll(store); } catch (e) { localRecords = []; }

      const localById = new Map(localRecords.map(r => [r.id, r]));

      // Secondary index by LRN for learner de-duplication
      const localByLRN = new Map();
      if (store === 'learners') {
        for (const r of localRecords) {
          if (r.lrn) localByLRN.set(String(r.lrn).trim(), r);
        }
      }

      let ins = 0, upd = 0, conf = 0, skip = 0;

      for (const remote of remoteRecords) {
        if (!remote || !remote.id) { skip++; continue; }

        const local = localById.get(remote.id);

        if (!local) {
          // Same LRN, different ID? Two devices independently created this
          // learner — surface as a conflict rather than inserting a duplicate.
          if (store === 'learners' && remote.lrn) {
            const dupLocal = localByLRN.get(String(remote.lrn).trim());
            if (dupLocal) {
              plan.conflicts.push({
                store, local: dupLocal, remote,
                reason: `Same LRN ${remote.lrn} but different internal IDs`
              });
              conf++;
              continue;
            }
          }
          plan.inserts.push({ store, record: remote, reason: 'Not present locally' });
          ins++;
          continue;
        }

        const cmp = this._compare(local, remote, store);
        if (cmp.winner === 'equal') {
          skip++;
        } else if (cmp.winner === 'remote') {
          plan.updates.push({
            store,
            record:   this._applyPreserve(local, remote, store),
            previous: local,
            reason:   cmp.reason
          });
          upd++;
        } else if (cmp.winner === 'conflict') {
          plan.conflicts.push({ store, local, remote, reason: cmp.reason });
          conf++;
        } else {
          skip++;
        }
      }

      plan.stats.perStore[store] = {
        local: localRecords.length,
        remote: remoteRecords.length,
        insert: ins, update: upd, conflict: conf, skip
      };
    }

    return plan;
  },

  _applyPreserve(local, remote, store) {
    const fields = this.PRESERVE_IF_REMOTE_EMPTY[store];
    if (!fields) return remote;
    const merged = Object.assign({}, remote);
    for (const f of fields) {
      if ((remote[f] === undefined || remote[f] === null || remote[f] === '') &&
          (local[f]  !== undefined && local[f]  !== null && local[f]  !== '')) {
        merged[f] = local[f];
      }
    }
    return merged;
  },

  /* ---- Apply a plan. All writes go through the atomic bulkWrite path. ---- */
  async applyPlan(plan, conflictPolicy = 'local') {
    const writes = {};
    const push = (store, rec) => {
      (writes[store] = writes[store] || []).push(rec);
    };

    for (const item of plan.inserts) push(item.store, item.record);
    for (const item of plan.updates) push(item.store, item.record);
    if (conflictPolicy === 'remote') {
      for (const item of plan.conflicts) push(item.store, item.remote);
    }

    let applied = 0;
    for (const [store, records] of Object.entries(writes)) {
      await DB.bulkWrite(store, records, 'put');
      applied += records.length;
    }

    DB._invalidate();
    return { applied };
  }
};
/* ============================================================================
   QR ATTENDANCE SCANNER
   ──────────────────────────────────────────────────────────────────────────
   Opens the rear camera, decodes QR codes from learner ID cards, and writes
   each successful scan directly to IndexedDB as Present. No save step.

   Design notes:
     • Scanning = committing. A scan is an explicit act; a save prompt would
       be friction without safety. Undo is available in the modal.
     • Debounce: the same QR stays in frame for many decode cycles. We mark
       once, then ignore that learner for 4 seconds.
     • No camera? Fall back to a manual LRN input. Never dead-end the teacher.
   ============================================================================ */
const QRAttendance = {
  _modal: null,
  _video: null,
  _canvas: null,
  _ctx: null,
  _stream: null,
  _timer: null,
  _recentScans: new Map(),   // learnerId → timestamp (debounce)
  _scans: [],                // { learner, at, status } in scan order
  _beepCtx: null,
  _attendanceRoot: null,

  /* ---------- Public entry ---------- */
  async open(attendanceRoot) {
    this._attendanceRoot = attendanceRoot;

    // Reset per-session state
    this._recentScans = new Map();
    this._scans = [];

    const ok = await this._ensureLib();
    if (!ok) {
      UI.toast('Could not load the QR reader. Check your connection, or vendor vendor/jsQR.js locally.', 'error', 7000);
      return;
    }

    this._renderModal();

    // Try to start the camera. If it fails, fall back to manual entry.
    try {
      await this._startCamera();
    } catch (e) {
      console.warn('[QR] Camera start failed:', e);
      this._showCameraError(e);
    }
  },

  /* ---------- Library loading ---------- */
  async _ensureLib() {
    if (window.jsQR) return true;

    return new Promise((resolve) => {
      const tryLoad = (src, onFail) => {
        const s = document.createElement('script');
        s.src = src;
        s.async = true;
        s.onload = () => resolve(!!window.jsQR);
        s.onerror = onFail;
        document.head.appendChild(s);
      };

      // Prefer the vendored copy so the feature works offline.
      tryLoad('./vendor/jsQR.js', () => {
        // Fall back to CDN if the vendored file is missing.
        console.warn('[QR] Vendored jsQR.js not found, falling back to CDN.');
        tryLoad('https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.js', () => resolve(false));
      });
    });
  },

  /* ---------- Modal construction ---------- */
  _renderModal() {
    const cls = State.activeClass || {};
    const learners = State.attendanceIncludeInactive
      ? State.learners
      : State.learners.filter(Utils.isActiveLearner);

    const modal = UI.modal({
      title: 'Scan Learner ID Cards',
      size: 'modal-lg',
      body: `
        <div class="qr-scanner-layout">
          <div class="qr-video-wrap" id="qr-video-wrap">
            <video id="qr-video" playsinline muted autoplay></video>
            <canvas id="qr-canvas" style="display:none;"></canvas>
            <div class="qr-reticle" aria-hidden="true">
              <span class="qr-reticle-corner tl"></span>
              <span class="qr-reticle-corner tr"></span>
              <span class="qr-reticle-corner bl"></span>
              <span class="qr-reticle-corner br"></span>
              <div class="qr-scanline"></div>
            </div>
            <div class="qr-flash" id="qr-flash"></div>
            <div class="qr-video-status" id="qr-video-status">Starting camera…</div>
          </div>

          <div class="qr-stats-row">
            <div class="qr-stat">
              <span class="qr-stat-label">Scanned</span>
              <span class="qr-stat-value" id="qr-count">0</span>
            </div>
            <div class="qr-stat">
              <span class="qr-stat-label">Total</span>
              <span class="qr-stat-value">${learners.length}</span>
            </div>
            <div class="qr-progress-wrap">
              <div class="qr-progress-bar"><div id="qr-progress-fill" style="width:0%"></div></div>
            </div>
          </div>

          <div class="qr-scan-list-wrap">
            <div class="qr-scan-list-head">
              <span>Scanned learners</span>
              <button type="button" class="btn btn-sm btn-ghost" id="qr-undo" disabled>Undo last</button>
            </div>
            <div class="qr-scan-list" id="qr-scan-list">
              <div class="qr-scan-empty">Point the camera at a learner ID card. Scans are saved immediately.</div>
            </div>
          </div>

          <div class="qr-manual-row">
            <label for="qr-manual-input" class="qr-manual-label">Or type an LRN manually:</label>
            <div class="qr-manual-input-wrap">
              <input type="text" id="qr-manual-input" class="form-control"
                     placeholder="12-digit LRN" inputmode="numeric" maxlength="14" autocomplete="off">
              <button type="button" class="btn btn-primary btn-sm" id="qr-manual-submit">Mark Present</button>
            </div>
          </div>
        </div>
      `,
      footer: `
        <button class="btn btn-outline" id="qr-close">Done</button>
      `,
      onClose: () => this._cleanup()
    });

    this._modal = modal;

    // Wire DOM references
    this._video = modal.overlay.querySelector('#qr-video');
    this._canvas = modal.overlay.querySelector('#qr-canvas');
    this._ctx = this._canvas.getContext('2d', { willReadFrequently: true });

    modal.overlay.querySelector('#qr-close').onclick = () => modal.close();
    modal.overlay.querySelector('#qr-undo').onclick = () => this._undoLast();
    modal.overlay.querySelector('#qr-manual-submit').onclick = () => this._manualSubmit();

    const manualInput = modal.overlay.querySelector('#qr-manual-input');
    manualInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') { e.preventDefault(); this._manualSubmit(); }
    });
  },

  /* ---------- Camera lifecycle ---------- */
  async _startCamera() {
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      throw new Error('This browser does not support camera access.');
    }

    this._stream = await navigator.mediaDevices.getUserMedia({
      video: {
        facingMode: { ideal: 'environment' },
        width:  { ideal: 1280 },
        height: { ideal: 720 }
      },
      audio: false
    });

    this._video.srcObject = this._stream;
    await this._video.play();

    this._setStatus('Scanning…');
    this._startDecodeLoop();
  },

  _stopCamera() {
    if (this._timer) { clearTimeout(this._timer); this._timer = null; }
    if (this._stream) {
      try { this._stream.getTracks().forEach(t => t.stop()); } catch (e) {}
      this._stream = null;
    }
    if (this._video) {
      try { this._video.srcObject = null; } catch (e) {}
    }
  },

  _startDecodeLoop() {
    const TICK_MS = 90;  // ~11 fps — plenty for QR, easy on the battery

    const tick = () => {
      if (!this._stream || !this._video) return;
      this._timer = setTimeout(tick, TICK_MS);

      const v = this._video;
      if (v.readyState !== v.HAVE_ENOUGH_DATA || !v.videoWidth) return;

      // Downscale for speed. jsQR on 800px-wide frames is ~4× faster
      // than on 1920px frames, with no loss of accuracy for QR codes.
      const MAX_W = 800;
      const scale = Math.min(1, MAX_W / v.videoWidth);
      this._canvas.width  = Math.round(v.videoWidth  * scale);
      this._canvas.height = Math.round(v.videoHeight * scale);
      this._ctx.drawImage(v, 0, 0, this._canvas.width, this._canvas.height);

      const imageData = this._ctx.getImageData(0, 0, this._canvas.width, this._canvas.height);

      let code = null;
      try {
        code = window.jsQR(imageData.data, imageData.width, imageData.height, {
          inversionAttempts: 'dontInvert'
        });
      } catch (e) {
        // Some browsers throw on rapidly-recycled ImageData; ignore.
      }

      if (code && code.data) this._handleDecoded(code.data);
    };

    tick();
  },

  _cleanup() {
    this._stopCamera();
    if (this._beepCtx) { try { this._beepCtx.close(); } catch (e) {} this._beepCtx = null; }

    // Refresh the attendance page behind us so the draft reflects every scan.
    if (this._attendanceRoot && document.body.contains(this._attendanceRoot)) {
      App.navigate('attendance');
    }
  },

  /* ---------- QR payload parsing ---------- */
  _parsePayload(text) {
    if (!text) return null;
    const s = String(text).trim();

    // 1. JSON (what our ID cards emit)
    if (s.startsWith('{')) {
      try {
        const obj = JSON.parse(s);
        if (obj && obj.lrn) return { lrn: String(obj.lrn).trim(), name: obj.name || '' };
      } catch (e) { /* fall through */ }
    }

    // 2. Bare numeric LRN
    const numeric = s.replace(/\D/g, '');
    if (numeric && numeric.length >= 6 && numeric.length <= 14) {
      return { lrn: numeric, name: '' };
    }

    // 3. Anything else — treat as a name fallback
    return { lrn: '', name: s };
  },

  /* ---------- Match a payload to a learner in the active class ---------- */
  _matchLearner(payload) {
    const learners = State.attendanceIncludeInactive
      ? State.learners
      : State.learners.filter(Utils.isActiveLearner);

    // Best signal: exact LRN match
    if (payload.lrn) {
      const byLrn = learners.find(l => String(l.lrn || '').trim() === payload.lrn);
      if (byLrn) return byLrn;
    }

    // Fallback: name match. Only used when no LRN was in the QR.
    if (payload.name) {
      const target = payload.name.toLowerCase().replace(/[,\s]+/g, ' ').trim();
      const byName = learners.find(l => {
        const full = Utils.fullName(l).toLowerCase().replace(/[,\s]+/g, ' ').trim();
        return full === target;
      });
      if (byName) return byName;
    }

    return null;
  },

  /* ---------- Handle a successful decode ---------- */
  async _handleDecoded(text) {
    const payload = this._parsePayload(text);
    if (!payload) return;

    const learner = this._matchLearner(payload);
    if (!learner) {
      // Unknown QR — this is not spam, it might be a learner from another class.
      // We throttle these warnings so they don't drown out the scans we care about.
      const now = Date.now();
      if (!this._lastUnknownWarn || now - this._lastUnknownWarn > 4000) {
        this._lastUnknownWarn = now;
        this._setStatus('QR not recognised in this class', 'warn');
        UI.toast('QR code is not from a learner in this class.', 'warning', 2500);
      }
      return;
    }

    // Debounce: same learner can appear in many frames
    const now = Date.now();
    const last = this._recentScans.get(learner.id) || 0;
    if (now - last < 4000) return;
    this._recentScans.set(learner.id, now);

    // Already scanned in this session?
    if (this._scans.some(s => s.learner.id === learner.id)) return;

    // Write to IndexedDB as Present
    await this._commitScan(learner);
  },

  async _commitScan(learner) {
    const date = State.attendanceDate || Utils.todayISO();
    const classId = State.activeClass.id;

    try {
      // Find existing record for this learner+date
      const existing = await DB.getAllByIndex('attendance', 'date', date);
      const rec = existing.find(a => a.learnerId === learner.id && a.classId === classId)
               || { id: Utils.uid('att-'), classId, learnerId: learner.id, date };

      rec.status = 'Present';
      rec.note = rec.note || '';
      rec.updatedAt = new Date().toISOString();
      if (!rec.createdAt) rec.createdAt = new Date().toISOString();
      rec.scannedAt = new Date().toISOString();

      await DB.put('attendance', rec);
    } catch (e) {
      console.error('[QR] Could not save scan:', e);
      UI.toast('Could not save scan. Try again.', 'error', 4000);
      return;
    }

    // Update in-memory draft so the attendance page reflects this immediately
    State.attendanceDraft = State.attendanceDraft || {};
    State.attendanceDraft[learner.id] = 'Present';
    State.attendanceDirty = true;

    // Keep the session from auto-locking while the teacher is scanning
    Session.touch();

    // Push into the visible list
    this._scans.push({ learner, at: new Date() });
    this._renderScanList();

    // Feedback
    this._beep();
    this._flash();
    this._setStatus(`✓ ${learner.firstName || Utils.fullName(learner)}`, 'ok');
  },

  async _undoLast() {
    const last = this._scans.pop();
    if (!last) return;
    this._renderScanList();

    // Remove the attendance record we just wrote
    try {
      const date = State.attendanceDate || Utils.todayISO();
      const existing = await DB.getAllByIndex('attendance', 'date', date);
      const rec = existing.find(a => a.learnerId === last.learner.id &&
                                      a.classId === State.activeClass.id);
      if (rec) await DB.delete('attendance', rec.id);

      if (State.attendanceDraft) delete State.attendanceDraft[last.learner.id];
    } catch (e) {
      console.warn('[QR] Undo failed:', e);
    }

    UI.toast(`Undone: ${last.learner.firstName || Utils.fullName(last.learner)}`, 'info', 2000);
  },

  async _manualSubmit() {
    const input = this._modal.overlay.querySelector('#qr-manual-input');
    const lrn = String(input.value || '').trim().replace(/\D/g, '');
    if (!lrn) { UI.toast('Enter an LRN.', 'warning'); return; }

    const learner = this._matchLearner({ lrn, name: '' });
    if (!learner) {
      UI.toast(`No learner in this class has LRN ${lrn}.`, 'warning', 4000);
      return;
    }
    if (this._scans.some(s => s.learner.id === learner.id)) {
      UI.toast('Already marked present in this session.', 'info', 2000);
      input.value = '';
      return;
    }

    input.value = '';
    await this._commitScan(learner);
  },

  /* ---------- Rendering ---------- */
  _renderScanList() {
    const list = this._modal.overlay.querySelector('#qr-scan-list');
    const countEl = this._modal.overlay.querySelector('#qr-count');
    const fill = this._modal.overlay.querySelector('#qr-progress-fill');
    const undoBtn = this._modal.overlay.querySelector('#qr-undo');
    if (!list) return;

    const learners = State.attendanceIncludeInactive
      ? State.learners
      : State.learners.filter(Utils.isActiveLearner);
    const total = Math.max(1, learners.length);

    countEl.textContent = String(this._scans.length);
    fill.style.width = Math.min(100, Math.round((this._scans.length / total) * 100)) + '%';
    undoBtn.disabled = this._scans.length === 0;

    if (this._scans.length === 0) {
      list.innerHTML = `<div class="qr-scan-empty">Point the camera at a learner ID card. Scans are saved immediately.</div>`;
      return;
    }

    // Newest first
    const reversed = this._scans.slice().reverse();
    list.innerHTML = reversed.map((s, i) => `
      <div class="qr-scan-row">
        <div class="qr-scan-avatar">${Utils.avatarHTML(s.learner, 30, 11)}</div>
        <div class="qr-scan-body">
          <div class="qr-scan-name">${Utils.esc(Utils.fullName(s.learner))}</div>
          <div class="qr-scan-meta">LRN ${Utils.esc(s.learner.lrn || '—')}</div>
        </div>
        <div class="qr-scan-time">${s.at.toLocaleTimeString('en-PH', { hour: '2-digit', minute: '2-digit' })}</div>
      </div>
    `).join('');
  },

  _setStatus(text, kind) {
    const el = this._modal && this._modal.overlay.querySelector('#qr-video-status');
    if (!el) return;
    el.textContent = text;
    el.dataset.kind = kind || '';
  },

  _flash() {
    const el = this._modal && this._modal.overlay.querySelector('#qr-flash');
    if (!el) return;
    el.classList.add('on');
    setTimeout(() => el.classList.remove('on'), 180);
  },

  _beep() {
    try {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (!Ctx) return;
      if (!this._beepCtx) this._beepCtx = new Ctx();
      const ctx = this._beepCtx;
      if (ctx.state === 'suspended') ctx.resume();

      const o = ctx.createOscillator();
      const g = ctx.createGain();
      o.type = 'sine';
      o.frequency.value = 1200;
      o.connect(g); g.connect(ctx.destination);

      const t = ctx.currentTime;
      g.gain.setValueAtTime(0, t);
      g.gain.linearRampToValueAtTime(0.18, t + 0.006);
      g.gain.exponentialRampToValueAtTime(0.001, t + 0.14);

      o.start(t);
      o.stop(t + 0.16);
    } catch (e) { /* audio is optional */ }
  },

  _showCameraError(err) {
    if (!this._modal) return;
    const wrap = this._modal.overlay.querySelector('#qr-video-wrap');
    if (!wrap) return;

    let msg = 'Camera unavailable.';
    if (err && err.name === 'NotAllowedError') msg = 'Camera permission was denied.';
    else if (err && err.name === 'NotFoundError') msg = 'No camera found on this device.';
    else if (err && err.name === 'NotReadableError') msg = 'Camera is already in use by another app.';
    else if (err && err.message) msg = err.message;

    wrap.innerHTML = `
      <div class="qr-camera-error">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="42" height="42">
          <path d="M23 19a2 2 0 01-2 2H3a2 2 0 01-2-2V8a2 2 0 012-2h4l2-3h6l2 3h4a2 2 0 012 2z"/>
          <circle cx="12" cy="13" r="4"/>
          <line x1="2" y1="2" x2="22" y2="22"/>
        </svg>
        <div class="qr-camera-error-title">${Utils.esc(msg)}</div>
        <div class="qr-camera-error-hint">You can still mark attendance using the LRN field below.</div>
      </div>`;
  }
};
/* ============================================================================
   VALIDATION ENGINE — checks required data is present before a report can be
   printed. Blocks on critical errors; allows (but flags) non-critical gaps.
   ============================================================================ */
const ValidationEngine = {
  validateSF2({ school, cls, learners, dates }) {
    const errors = [], warnings = [];
    if (!school || !school.name) errors.push('School Name is missing (Settings → School Profile).');
    if (!school || !school.schoolId) errors.push('School ID is missing (Settings → School Profile).');
    if (!cls) errors.push('No class selected.');
    if (!learners || !learners.length) warnings.push('This class has no learners.');
    if (!dates || !dates.length) warnings.push('No attendance has been recorded for this class in the selected month.');
    if (school && !school.region) warnings.push('Region is missing.');
    if (school && !school.division) warnings.push('Division is missing.');
    if (school && !school.schoolHead) warnings.push('School Head name is missing.');
    if (cls && !cls.adviser) warnings.push('Adviser name is missing on this class.');
    return { errors, warnings };
  },
  validateSF9({ school, cls, learnerData, term }) {
    const errors = [], warnings = [];
    if (!school || !school.name) errors.push('School Name is missing (Settings → School Profile).');
    if (school && !school.schoolId) warnings.push('School ID is missing.');
    if (school && !school.schoolHead) warnings.push('School Head name is missing.');
    if (cls && !cls.adviser) warnings.push('Adviser name is missing on this class.');
    (learnerData || []).forEach(d => {
      const name = d.l ? Utils.fullName(d.l) : 'Unknown learner';
      if (!d.l || !d.l.lrn) warnings.push(name + ': LRN is missing.');
      if (!d.l || !d.l.sex) warnings.push(name + ': Sex is missing.');
      if (d.source === 'missing') warnings.push(name + ': ' + term + ' has not been finalized in the Gradebook yet — this learner will print with no grade for that period.');
      if (d.source === 'incomplete') warnings.push(name + ': not all terms are finalized yet — Final Grade will be incomplete.');
    });
    return { errors, warnings };
  }
};


/* ============================================================================
   PLATFORM DETECTION — used for storage warnings
   ============================================================================ */
function detectSafariNoPWA() {
  try {
    const ua = navigator.userAgent || '';
    const isSafari = /Safari/.test(ua) && !/Chrome|Chromium|Edg|OPR|CriOS|FxiOS|Brave/.test(ua);
    const isIOS = /iPhone|iPad|iPod/.test(ua) || (/Macintosh/.test(ua) && navigator.maxTouchPoints > 1);
    const standalone = (typeof navigator.standalone !== 'undefined' && navigator.standalone === true)
      || (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches);
    return { isSafari, isIOS, standalone, needsWarning: (isSafari || isIOS) && !standalone };
  } catch (e) {
    return { isSafari: false, isIOS: false, standalone: false, needsWarning: false };
  }
}

/* ============================================================================
   UTILITIES
   ============================================================================ */

const Utils = {
  uid(prefix = '') { return prefix + Date.now().toString(36) + Math.random().toString(36).slice(2, 9); },
  esc(str) {
    if (str === null || str === undefined) return '';
    return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  },
  attr(str) { return this.esc(str); },
  
  /**
   * Safely toggle a class on an element, coercing the force argument
   * to a real boolean. Prevents the classic footgun where an
   * `undefined` force argument is treated by the DOM spec as
   * "not passed at all", causing toggle to flip the class instead
   * of forcing it on or off.
   *
   * Accepts either an Element or a CSS selector string.
   * Returns true if the class is now present, false otherwise.
   */
  setClass(target, className, force) {
    const el = typeof target === 'string'
      ? document.querySelector(target)
      : target;
    if (!el || !el.classList) return false;
    el.classList.toggle(className, !!force);
    return el.classList.contains(className);
  },
  // ↑↑↑ END ADD ↑↑↑
  todayISO() {
    const d = new Date();
    return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
  },
    /* Filename-safe timestamp: 2026-10-02_143722
     • Colons are omitted — they break filenames on Windows.
     • YYYY-MM-DD_HHMMSS sorts lexicographically = chronologically,
       so backup folders list newest-last automatically. */
  timestampForFilename(date = new Date()) {
    const d = date instanceof Date ? date : new Date(date);
    if (isNaN(d)) return 'unknown';
    const pad = (n) => String(n).padStart(2, '0');
    return (
      d.getFullYear() + '-' +
      pad(d.getMonth() + 1) + '-' +
      pad(d.getDate()) + '_' +
      pad(d.getHours()) +
      pad(d.getMinutes()) +
      pad(d.getSeconds())
    );
  },
    /* Alias used throughout the codebase. Produces the same filename-safe
    stamp as timestampForFilename() so the two names are interchangeable. */
  timestamp(date = new Date()) { return this.timestampForFilename(date); },

  formatDate(iso, opts = {}) {
    if (!iso) return '—';
    const d = new Date(iso); if (isNaN(d)) return '—';
    const o = Object.assign({ year: 'numeric', month: 'short', day: 'numeric' }, opts);
    return d.toLocaleDateString('en-PH', o);
  },
  formatDateTime(iso) {
    if (!iso) return '—';
    const d = new Date(iso); if (isNaN(d)) return '—';
    return d.toLocaleString('en-PH', { year:'numeric', month:'short', day:'numeric', hour:'2-digit', minute:'2-digit' });
  },
  timeAgo(iso) {
    const d = new Date(iso); const diff = (Date.now() - d.getTime()) / 1000;
    if (diff < 60) return 'just now';
    if (diff < 3600) return Math.floor(diff/60) + 'm ago';
    if (diff < 86400) return Math.floor(diff/3600) + 'h ago';
    if (diff < 604800) return Math.floor(diff/86400) + 'd ago';
    return this.formatDate(iso);
  },
  calcAge(birthDate) {
    if (!birthDate) return '';
    const b = new Date(birthDate); if (isNaN(b)) return '';
    const today = new Date();
    let age = today.getFullYear() - b.getFullYear();
    const m = today.getMonth() - b.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < b.getDate())) age--;
    return age >= 0 && age < 150 ? age : '';
  },
  fullName(l) {
    if (!l) return 'Unknown';
    return [l.firstName, l.middleName, l.lastName, l.suffix].filter(Boolean).join(' ');
  },
  displayName(l) {
    if (!l) return 'Unknown';
    const m = l.middleName ? l.middleName.charAt(0).toUpperCase() + '.' : '';
    return [l.lastName + ',', l.firstName, m, l.suffix].filter(Boolean).join(' ');
  },
  lastNameFirst(l) {
    if (!l) return 'Unknown';
    const m = l.middleName ? l.middleName.charAt(0).toUpperCase() + '.' : '';
    return [l.lastName + ',', l.firstName, m, l.suffix].filter(Boolean).join(' ');
  },
  initials(name) {
    if (!name) return '?';
    return name.split(/\s+/).filter(Boolean).slice(0,2).map(w => w[0].toUpperCase()).join('');
  },
  sortAlpha(arr, key) {
    return [...arr].sort((a, b) => {
      const av = (a[key] || '').toString().toLowerCase();
      const bv = (b[key] || '').toString().toLowerCase();
      return av.localeCompare(bv);
    });
  },
  avg(arr) {
    const nums = arr.filter(n => typeof n === 'number' && !isNaN(n));
    if (!nums.length) return 0;
    return nums.reduce((a,b)=>a+b,0) / nums.length;
  },
  median(arr) {
    const nums = arr.filter(n => typeof n === 'number' && !isNaN(n)).sort((a,b)=>a-b);
    if (!nums.length) return 0;
    const mid = Math.floor(nums.length/2);
    return nums.length % 2 ? nums[mid] : (nums[mid-1]+nums[mid])/2;
  },
  round(n, d = 2) { const f = Math.pow(10, d); return Math.round(n * f) / f; },
  clamp(n, min, max) { return Math.max(min, Math.min(max, n)); },
  debounce(fn, ms = 250) {
    let t;
    return (...args) => { clearTimeout(t); t = setTimeout(() => fn(...args), ms); };
  },
  download(filename, content, mime = 'application/json') {
    const blob = new Blob([content], { type: mime });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = filename;
    document.body.appendChild(a); a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  },
  csvEscape(val) {
    if (val === null || val === undefined) return '';
    const s = String(val);
    if (/[",\n\r]/.test(s)) return '"' + s.replace(/"/g, '""') + '"';
    return s;
  },
  toCSV(rows, headers) {
    const out = [];
    if (headers) out.push(headers.map(h => this.csvEscape(h.label !== undefined ? h.label : h)).join(','));
    const keys = headers ? headers.map(h => h.key !== undefined ? h.key : h) : Object.keys(rows[0] || {});
    rows.forEach(r => { out.push(keys.map(k => this.csvEscape(r[k])).join(',')); });
    return out.join('\n');
  },
  parseCSV(text) {
    const rows = []; let cur = [], field = '', inQuotes = false;
    text = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
    for (let i = 0; i < text.length; i++) {
      const c = text[i];
      if (inQuotes) {
        if (c === '"') { if (text[i+1] === '"') { field += '"'; i++; } else inQuotes = false; }
        else field += c;
      } else {
        if (c === '"') inQuotes = true;
        else if (c === ',') { cur.push(field); field = ''; }
        else if (c === '\n') { cur.push(field); rows.push(cur); cur = []; field = ''; }
        else field += c;
      }
    }
    if (field !== '' || cur.length) { cur.push(field); rows.push(cur); }
    return rows.filter(r => r.some(c => c !== ''));
  },
  readFile(file, as = 'text') {
    return new Promise((resolve, reject) => {
      const r = new FileReader();
      r.onload = () => resolve(r.result);
      r.onerror = () => reject(r.error);
      if (as === 'dataURL') r.readAsDataURL(file);
      else r.readAsText(file);
    });
  },
  processImage(file, maxSize = CONFIG.PHOTO_MAX_SIZE, quality = CONFIG.PHOTO_QUALITY) {
    return new Promise((resolve, reject) => {
      if (!file) { reject(new Error('No file')); return; }
      if (!/^image\//.test(file.type)) { reject(new Error('Not an image')); return; }
      const reader = new FileReader();
      reader.onerror = () => reject(reader.error || new Error('Read failed'));
      reader.onload = (e) => {
        const img = new Image();
        img.onerror = () => reject(new Error('Decode failed'));
        img.onload = () => {
          try {
            let { width, height } = img;
            if (width > height && width > maxSize) { height = Math.round(height * maxSize / width); width = maxSize; }
            else if (height > maxSize) { width = Math.round(width * maxSize / height); height = maxSize; }
            const canvas = document.createElement('canvas');
            canvas.width = width; canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx.imageSmoothingEnabled = true;
            ctx.imageSmoothingQuality = 'high';
            ctx.drawImage(img, 0, 0, width, height);
            resolve(canvas.toDataURL('image/jpeg', quality));
          } catch (err) { reject(err); }
        };
        img.src = e.target.result;
      };
      reader.readAsDataURL(file);
    });
  },
  avatarHTML(learner, size = 32, fontSize = 12) {
    if (!learner) return `<div class="mini-avatar" style="width:${size}px;height:${size}px;font-size:${fontSize}px;background:#627D98;">?</div>`;
    if (learner.photo) {
      return `<div class="mini-avatar" style="width:${size}px;height:${size}px;font-size:${fontSize}px;"><img src="${Utils.esc(learner.photo)}" alt="" loading="lazy" decoding="async"></div>`;
    }
    const bg = Utils.colorFor(Utils.fullName(learner));
    return `<div class="mini-avatar" style="width:${size}px;height:${size}px;font-size:${fontSize}px;background:${bg};">${Utils.esc(Utils.initials(Utils.fullName(learner)))}</div>`;
  },
  gradeRemarks(grade) {
    if (grade === '' || grade === null || grade === undefined || isNaN(grade)) return { label: '—', cls: '' };
    const g = Number(grade);
    if (g >= 90) return { label: 'Outstanding', cls: 'grade-outstanding' };
    if (g >= 85) return { label: 'Very Satisfactory', cls: 'grade-verysatisfactory' };
    if (g >= 80) return { label: 'Satisfactory', cls: 'grade-satisfactory' };
    if (g >= 75) return { label: 'Fairly Satisfactory', cls: 'grade-fairly' };
    return { label: 'Did Not Meet Expectations', cls: 'grade-didnot' };
  },
  transmute(initial) {
    if (initial === null || initial === undefined || isNaN(initial)) return '';
    const g = Number(initial);
    const table = [
      [100,100],[98.40,99],[96.80,98],[95.20,97],[93.60,96],[92.00,95],
      [90.40,94],[88.80,93],[87.20,92],[85.60,91],[84.00,90],[82.40,89],
      [80.80,88],[79.20,87],[77.60,86],[76.00,85],[74.40,84],[72.80,83],
      [71.20,82],[69.60,81],[68.00,80],[66.40,79],[64.80,78],[63.20,77],
      [61.60,76],[60.00,75],[56.00,74],[52.00,73],[48.00,72],[44.00,71],
      [40.00,70],[36.00,69],[32.00,68],[28.00,67],[24.00,66],[20.00,65],
      [16.00,64],[12.00,63],[8.00,62],[4.00,61],[0,60]
    ];
    for (const [init, trans] of table) if (g >= init) return trans;
    return 60;
  },
  colorFor(str) {
    const colors = ['#0038A8','#0057B8','#198754','#F59E0B','#DC3545','#7C3AED','#0891B2','#BE185D'];
    let h = 0;
    for (let i = 0; i < (str || '').length; i++) h = (h * 31 + str.charCodeAt(i)) % colors.length;
    return colors[Math.abs(h)];
  },

   // Normalize a sex value to 'Male' | 'Female' | '' so that values
  // imported from an SF1 (.xlsx or CSV) — which use single letters
  // M/F — bucket consistently with values entered through the
  // learner form (which stores 'Male'/'Female').
  normalizeSex(raw) {
    const s = String(raw == null ? '' : raw).trim().toLowerCase();
    if (!s) return '';
    if (s === 'm' || s === 'male') return 'Male';
    if (s === 'f' || s === 'female') return 'Female';
    return String(raw).trim(); // preserve anything else verbatim
  },

    /** A learner is eligible for interactive tools (attendance, picker,
      wheel, groupings) only when their status is explicitly 'Active'.
      A missing / blank status is treated as Active — this is the safest
      default: an incomplete record must never silently hide a learner. */
  isActiveLearner(l) {
    if (!l) return false;
    const raw = l.status;
    if (raw === undefined || raw === null || String(raw).trim() === '') return true;
    return String(raw).trim().toLowerCase() === 'active';
  },
 
};



/* ============================================================================
   SECURITY — Web Crypto
   ============================================================================ */
const Security = {
  available() {
    return typeof crypto !== 'undefined' && crypto.subtle && typeof crypto.getRandomValues === 'function';
  },
  toHex(buf) { return [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, '0')).join(''); },
  hexToBuf(hex) {
    const bytes = new Uint8Array(hex.length / 2);
    for (let i = 0; i < bytes.length; i++) bytes[i] = parseInt(hex.substr(i * 2, 2), 16);
    return bytes;
  },
  randomHex(bytes = CONFIG.SALT_BYTES) {
    const arr = new Uint8Array(bytes);
    crypto.getRandomValues(arr);
    return this.toHex(arr);
  },
  async deriveKey(password, saltHex, iterations = CONFIG.PBKDF2_ITERATIONS, hash = CONFIG.PBKDF2_HASH) {
    const enc = new TextEncoder();
    const keyMaterial = await crypto.subtle.importKey('raw', enc.encode(password), { name: 'PBKDF2' }, false, ['deriveBits']);
    const bits = await crypto.subtle.deriveBits(
      { name: 'PBKDF2', salt: this.hexToBuf(saltHex), iterations, hash },
      keyMaterial, CONFIG.KEY_LENGTH_BITS
    );
    return this.toHex(bits);
  },

    /** Pick an iteration count appropriate for this device.
      A local app lock does not need 200k PBKDF2 iterations the way a
      server-side password store does — the attacker already has physical
      access to the database file, so the marginal security gain from
      200k vs 100k iterations is small, while the UX cost on mobile is
      enormous. We aim for a ~400–800 ms verification on the device. */
  adaptiveIterations() {
    try {
      const cores = navigator.hardwareConcurrency || 2;
      const mem = navigator.deviceMemory || 4;       // Chrome/Android only
      const isMobile = /Android|iPhone|iPad|iPod|Mobile|Opera Mini/i.test(navigator.userAgent);
      const isLowEnd = (mem <= 2) || (cores <= 4 && isMobile);

      if (isLowEnd)             return 60000;   // low-end phone / tablet
      if (isMobile)             return 100000;  // modern phone
      if (cores <= 4)           return 120000;  // weak laptop / netbook
      return 150000;                            // desktop
    } catch (e) {
      return 100000; // conservative fallback
    }
  },
  async hashPassword(password) {
    const salt = this.randomHex(CONFIG.SALT_BYTES);
    const iterations = this.adaptiveIterations();   // ← was CONFIG.PBKDF2_ITERATIONS
    const verifier = await this.deriveKey(password, salt, iterations);
    return { version: 1, algorithm: 'PBKDF2-' + CONFIG.PBKDF2_HASH, iterations, salt, verifier };
  },
  async verifyPassword(password, record) {
    if (!record || !record.salt || !record.verifier) return false;
    const derived = await this.deriveKey(password, record.salt, record.iterations || CONFIG.PBKDF2_ITERATIONS, (record.algorithm || '').replace('PBKDF2-','') || CONFIG.PBKDF2_HASH);
    return this.constantTimeEqual(derived, record.verifier);
  },
  constantTimeEqual(a, b) {
    if (typeof a !== 'string' || typeof b !== 'string') return false;
    if (a.length !== b.length) return false;
    let diff = 0;
    for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
    return diff === 0;
  },
  generateRecoveryKey() {
    const bytes = new Uint8Array(8);
    crypto.getRandomValues(bytes);
    const hex = this.toHex(bytes).toUpperCase();
    return hex.match(/.{1,4}/g).join('-');
  },
  async hashRecoveryKey(key) {
    const enc = new TextEncoder();
    const norm = key.replace(/[^A-Za-z0-9]/g, '').toUpperCase();
    const buf = await crypto.subtle.digest('SHA-256', enc.encode('KlazAssistRecovery|' + norm));
    return this.toHex(buf);
  },
  passwordStrength(pw) {
    if (!pw) return { level: 0, label: '—', suggestions: ['Enter a password'] };
    let score = 0;
    const reasons = [];
    if (pw.length >= 8) score++; else reasons.push('Use at least 8 characters');
    if (pw.length >= 12) score++;
    const hasLower = /[a-z]/.test(pw);
    const hasUpper = /[A-Z]/.test(pw);
    const hasDigit = /\d/.test(pw);
    const hasSym = /[^A-Za-z0-9]/.test(pw);
    const variety = [hasLower, hasUpper, hasDigit, hasSym].filter(Boolean).length;
    if (variety >= 2) score++;
    if (variety >= 3 && pw.length >= 10) score++;
    const lower = pw.toLowerCase();
    if (CONFIG.COMMON_PASSWORDS.some(c => lower.includes(c))) {
      score = Math.min(score, 1);
      reasons.push('Avoid common passwords');
    }
    if (/^(.)\1+$/.test(pw)) { score = Math.min(score, 1); reasons.push('Avoid repeated characters'); }
    if (/^\d+$/.test(pw)) { score = Math.min(score, 1); reasons.push('Avoid all-numbers passwords'); }
    score = Utils.clamp(score, 0, 4);
    const labels = ['Very Weak', 'Weak', 'Fair', 'Strong', 'Very Strong'];
    if (!reasons.length) {
      if (!hasUpper) reasons.push('Add an uppercase letter');
      if (!hasDigit) reasons.push('Add a number');
      if (!hasSym) reasons.push('Add a symbol for extra strength');
    }
    return { level: score, label: labels[score], suggestions: reasons.slice(0, 3) };
  },
  meetsMinimum(pw) {
    if (!pw || typeof pw !== 'string') return false;
    if (pw.trim().length < 8) return false;
    const lower = pw.toLowerCase();
    if (CONFIG.COMMON_PASSWORDS.some(c => lower === c)) return false;
    if (/^\d+$/.test(pw)) return false;
    if (/^(.)\1+$/.test(pw)) return false;
    return true;
  }
};

/* ============================================================================
   LICENSING — offline Ed25519 license verification
   ============================================================================ */
const Licensing = {
  STORAGE_KEY: 'license.current',
  PUBLIC_KEY_B64U: '4VWk-6OWCcgblrbZxO8HkZJfZ__J43lf9f7Zk_PjFiQ', // ← from Step 1

  _license: null,
  _pubKeyCache: null,

  /* Load + verify any stored license at boot */
  async init() {
    try {
      const stored = await DB.getSetting(this.STORAGE_KEY, null);
      if (!stored || !stored.payload || !stored.signature) return null;
      const valid = await this._verify(stored);
      if (!valid) {
        console.warn('[Licensing] Stored license failed signature check.');
        return null;
      }
      if (stored.payload.expires && new Date(stored.payload.expires) < new Date()) {
        console.warn('[Licensing] Stored license has expired.');
        return null;
      }
      this._license = stored;
      return stored;
    } catch (e) {
      console.warn('[Licensing] Init failed:', e);
      return null;
    }
  },

  /* Parse, verify, and persist a license key */
  async activate(keyText) {
    const parsed = this._parseKey(keyText);
    if (!parsed) throw new Error('This does not look like a KlazAssist license key.');

    const valid = await this._verify(parsed);
    if (!valid) throw new Error('License signature is invalid — the key may be mistyped or tampered with.');

    if (parsed.payload.expires && new Date(parsed.payload.expires) < new Date()) {
      throw new Error('This license expired on ' +
        new Date(parsed.payload.expires).toLocaleDateString('en-PH') + '.');
    }
    if (parsed.payload.tier !== 'pro' && parsed.payload.tier !== 'school') {
      throw new Error('This license does not grant Pro access.');
    }

    await DB.setSetting(this.STORAGE_KEY, parsed);
    this._license = parsed;
    App.logActivity(`License activated (${parsed.payload.tier})`, 'Licensing');
    return parsed;
  },

  async deactivate() {
    await DB.deleteSetting(this.STORAGE_KEY);
    this._license = null;
    App.logActivity('License deactivated', 'Licensing');
  },

  isPro() {
    if (!this._license) return false;
    const p = this._license.payload;
    if (p.tier !== 'pro' && p.tier !== 'school') return false;
    if (p.expires && new Date(p.expires) < new Date()) return false;
    return true;
  },

  getLicense() { return this._license; },

  /* ---- License holder metadata (read-only, set at activation time) ---- */
  getHolderName() {
    if (!this._license || !this._license.payload) return null;
    return this._license.payload.name || this._license.payload.email || null;
  },
  getHolderEmail() {
    if (!this._license || !this._license.payload) return null;
    return this._license.payload.email || null;
  },
  getHolderSchool() {
    if (!this._license || !this._license.payload) return null;
    return this._license.payload.school || null;
  },

  /**
   * The single source of truth for "whose name goes on printed reports".
   *
   * Pro (individual) tier → license holder name, full stop. This overrides
   *   both the class adviser and the Teacher Profile name. If a teacher
   *   shares their key, the borrower's reports carry the buyer's name.
   * School tier → the school name (the license belongs to the institution).
   * No license → falls back to class adviser, then Teacher Profile name.
   */
  getReportSignatory(cls) {
    if (this.isPro()) {
      if (this._license.payload.tier === 'school') {
        const school = this.getHolderSchool();
        if (school) return school;
      }
      const holder = this.getHolderName();
      if (holder) return holder;
    }
    if (cls && cls.adviser && String(cls.adviser).trim()) return cls.adviser.trim();
    return (State.currentUser && State.currentUser.fullName) || '';
  },

  /**
   * True only when Pro is active AND the signatory is locked by the license.
   * Used to grey out the "Full Name" hint on the Teacher Profile page.
   */
  isSignatoryLocked() {
    return this.isPro() && this._license.payload.tier === 'pro' && !!this.getHolderName();
  },

  /* ---------- internals ---------- */

  _parseKey(text) {
    const clean = String(text || '').trim().replace(/\s+/g, '');
    const parts = clean.split('.');
    if (parts.length !== 3 || parts[0] !== 'KLAZ1') return null;
    try {
      const payloadJson = this._b64uDecode(parts[1], false);
      const payload = JSON.parse(payloadJson);
      const signature = this._b64uDecode(parts[2], true);
      return { payload, signature, raw: clean };
    } catch (e) { return null; }
  },

  async _verify(license) {
    try {
      const key = await this._importPublicKey();
      const payloadBytes = new TextEncoder().encode(JSON.stringify(license.payload));
      const sigBytes = license.signature instanceof Uint8Array
        ? license.signature
        : new Uint8Array(license.signature);
      return await crypto.subtle.verify({ name: 'Ed25519' }, key, sigBytes, payloadBytes);
    } catch (e) {
      console.error('[Licensing] Verify error:', e);
      return false;
    }
  },

  async _importPublicKey() {
    if (this._pubKeyCache) return this._pubKeyCache;
    const raw = this._b64uDecode(this.PUBLIC_KEY_B64U, true);
    this._pubKeyCache = await crypto.subtle.importKey(
      'raw', raw, { name: 'Ed25519' }, false, ['verify']
    );
    return this._pubKeyCache;
  },

  _b64uDecode(str, toBytes) {
    const b64 = String(str).replace(/-/g, '+').replace(/_/g, '/');
    const pad = b64.length % 4 ? '='.repeat(4 - (b64.length % 4)) : '';
    const binary = atob(b64 + pad);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return toBytes ? bytes : new TextDecoder().decode(bytes);
  }
};
/* ============================================================================
   WRITE VALIDATORS
   Cheap, per-store sanity checks that run before every DB.put().
   Each validator either returns normally (record is fine) or throws with a
   message the caller can surface to the user.
   ============================================================================ */
const WRITE_VALIDATORS = {
  learners(l) {
    if (!l) throw new Error('Learner record is empty.');
    if (!String(l.firstName || '').trim() && !String(l.lastName || '').trim()) {
      throw new Error('A learner needs at least a first or last name.');
    }
    if (l.lrn && !/^\d{3,14}$/.test(String(l.lrn))) {
      throw new Error('LRN must be 3–14 digits.');
    }
    if (l.birthDate && !/^\d{4}-\d{2}-\d{2}$/.test(l.birthDate)) {
      throw new Error('Birth date must be in YYYY-MM-DD format.');
    }
  },

  attendance(a) {
    if (!a) throw new Error('Attendance record is empty.');
    if (!a.date || !/^\d{4}-\d{2}-\d{2}$/.test(a.date)) {
      throw new Error('Attendance date must be in YYYY-MM-DD format.');
    }
    if (!['Present', 'Absent', 'Late', 'Excused'].includes(a.status)) {
      throw new Error('Invalid attendance status.');
    }
  },

  assessmentResults(r) {
    if (!r) throw new Error('Result record is empty.');
    const score = Number(r.score) || 0;
    const max   = Number(r.maxScore) || 0;
    if (max > 0 && score > max) {
      throw new Error(`Score (${score}) cannot exceed the maximum (${max}).`);
    }
    if (score < 0) {
      throw new Error('Score cannot be negative.');
    }
  },

  termGrades(g) {
    if (!g) throw new Error('Term grade record is empty.');
    const r = Number(g.reportedGrade);
    if (g.reportedGrade !== '' && g.reportedGrade != null && !isNaN(r)) {
      if (r < 0 || r > 100) throw new Error('Reported grade must be between 0 and 100.');
    }
  }
};

/* ============================================================================
   INDEXEDDB
   ============================================================================ */
const DB = {
  db: null, initPromise: null, initFailed: false,
    _caches: null,
  _activeToken: null,

  beginCache() {
    if (!this._caches) this._caches = new Map();
    const token = Symbol('render');
    this._caches.set(token, new Map());
    this._activeToken = token;
    return token;
  },

  endCache(token) {
    if (!this._caches) return;
    const t = token || this._activeToken;
    if (t) this._caches.delete(t);
    if (t === this._activeToken) {
      // Fall back to the most recently created cache that still exists.
      const remaining = Array.from(this._caches.keys());
      this._activeToken = remaining.length ? remaining[remaining.length - 1] : null;
    }
  },

  _invalidate() {
    if (this._caches) {
      for (const c of this._caches.values()) c.clear();
    }
  },

  _activeCache() {
    if (!this._caches || !this._activeToken) return null;
    return this._caches.get(this._activeToken) || null;
  },
  open() {
    if (this.db) {
      try {
        // A closed IDBDatabase object can remain referenced after another
        // tab/version change. Treat it as unusable and reopen cleanly.
        if (this.db.objectStoreNames) return Promise.resolve(this.db);
      } catch (_) {}
      this.db = null;
    }
    if (this.initPromise) return this.initPromise;

    this.initPromise = new Promise((resolve, reject) => {
      if (!window.indexedDB) {
        this.initFailed = true;
        reject(new Error('IndexedDB is not supported by this browser.'));
        return;
      }

      let request;
      try {
        request = window.indexedDB.open(CONFIG.DB_NAME, CONFIG.DB_VERSION);
      } catch (e) {
        this.initFailed = true;
        reject(e);
        return;
      }

      let upgradeError = null;

      request.onupgradeneeded = (event) => {
        const db = event.target.result;
        const tx = event.target.transaction;

        try {
          // Phase 1: create every required store. Never swallow a schema
          // mutation error: a failed migration must abort atomically.
          for (const name of CONFIG.STORES) {
            if (!db.objectStoreNames.contains(name)) {
              db.createObjectStore(name, { keyPath: 'id' });
            }
          }

          // Phase 2: create/repair indexes. Existing indexes are checked by
          // BOTH name and keyPath. Older KlazAssist builds sometimes created
          // an index with the same name but a different key path; simply
          // skipping such an index leaves the schema logically broken.
          const indexSpecs = {
            learners: [
              ['lrn', 'lrn'], ['lastName', 'lastName'], ['classId', 'classId'],
              ['classId_lastName', ['classId', 'lastName']]
            ],
            attendance: [
              ['date', 'date'], ['classId', 'classId'], ['learnerId', 'learnerId'],
              ['classId_date', ['classId', 'date']], ['learnerId_date', ['learnerId', 'date']]
            ],
            assessmentResults: [
              ['assessmentId', 'assessmentId'], ['learnerId', 'learnerId'],
              ['classId', 'classId'], ['learnerId_assessmentId', ['learnerId', 'assessmentId']]
            ],
            grades: [['learnerId', 'learnerId'], ['classId', 'classId']],
            notes: [['category', 'category']],
            activityLogs: [['timestamp', 'timestamp']],
            termGrades: [
              ['classId', 'classId'], ['learnerId', 'learnerId'],
              ['classTerm', ['classId', 'term', 'schoolYear']],
              ['classId_term', ['classId', 'term']]
            ],
            reportSnapshots: [
              ['classId', 'classId'], ['learnerId', 'learnerId'], ['reportType', 'reportType']
            ],
            sf9Records: [
              ['classId', 'classId'], ['learnerId', 'learnerId'],
              ['classLearnerYear', ['classId', 'learnerId', 'schoolYear']]
            ],
            rubrics: [
              ['classId', 'classId'], ['subject', 'subject'],
              ['taskType', 'taskType'], ['createdAt', 'createdAt']
            ],
            assessments: [
              ['classId', 'classId'], ['classId_term', ['classId', 'term']]
            ],
            assignments: [
              ['classId', 'classId'], ['classId_status', ['classId', 'status']]
            ],
            schedules: [
              ['classId', 'classId'], ['classId_day', ['classId', 'day']]
            ],
            behaviorLogs: [['classId', 'classId'], ['learnerId', 'learnerId']],
            parentLogs: [['classId', 'classId'], ['learnerId', 'learnerId']],
            groups: [['classId', 'classId']],
            weeklyPlans: [
              ['classId', 'classId'], ['classId_date', ['classId', 'date']]
            ],
            lessonPlans: [['classId', 'classId']],
            calendarEvents: [
              ['classId', 'classId'], ['date', 'date'], ['source', 'source']
            ],
            presentations: [['classId', 'classId']],
            teachingLoad: [['subject', 'subject']]
          };

          for (const [storeName, specs] of Object.entries(indexSpecs)) {
            const store = tx.objectStore(storeName);

            for (const [indexName, keyPath] of specs) {
              let needsCreate = true;

              if (store.indexNames.contains(indexName)) {
                const existing = store.index(indexName);
                const existingPath = JSON.stringify(existing.keyPath);
                const requiredPath = JSON.stringify(keyPath);

                if (existingPath === requiredPath) {
                  needsCreate = false;
                } else {
                  // Upgrade-time deleteIndex is atomic with the schema
                  // transaction. Recreate it immediately with the correct
                  // key path.
                  store.deleteIndex(indexName);
                }
              }

              if (needsCreate) {
                store.createIndex(indexName, keyPath, { unique: false });
              }
            }
          }
        } catch (e) {
          upgradeError = e;
          console.error('[DB] Schema migration failed; transaction will abort.', e);
          try { tx.abort(); } catch (_) {}
          // Do not continue to onsuccess with a partially migrated schema.
        }
      };

      request.onsuccess = (event) => {
        if (upgradeError) {
          // Defensive: IndexedDB normally routes an aborted upgrade to
          // request.onerror. Do not expose a database that failed migration.
          try { event.target.result.close(); } catch (_) {}
          this.db = null;
          this.initFailed = true;
          reject(upgradeError);
          return;
        }

        const db = event.target.result;
        this.db = db;

        db.onversionchange = () => {
          try { db.close(); } catch (_) {}
          if (this.db === db) this.db = null;
          this.initFailed = true;
          console.warn('[DB] Database version changed in another tab; local connection closed.');
        };

        db.onclose = () => {
          if (this.db === db) this.db = null;
        };

        db.onerror = (e) => {
          console.error('[DB] Runtime database error:', e && e.target ? e.target.error : e);
        };

        this.initFailed = false;
        resolve(db);
      };

      request.onerror = (event) => {
        this.initFailed = true;
        const err = event.target.error || upgradeError ||
          new Error('Database open failed.');
        console.error('[DB] Open/migration error:', err);
        reject(err);
      };

      request.onblocked = () => {
        this.initFailed = true;
        reject(new Error(
          'Database upgrade is blocked by another KlazAssist tab or window. ' +
          'Close other KlazAssist tabs, then click Retry.'
        ));
      };
    });

    // A failed promise must never poison future retry attempts.
    this.initPromise.catch(() => {
      this.initPromise = null;
    });

    return this.initPromise;
  },
  retryInit() {
    this.db = null; this.initPromise = null; this.initFailed = false;
    document.getElementById('db-error-screen').classList.add('hidden');
    document.getElementById('loading-screen').classList.remove('hidden');
    App.bootstrap();
  },
  tx(storeNames, mode = 'readonly') {
    if (!this.db) throw new Error('Database not initialized');
    return this.db.transaction(storeNames, mode);
  },
  req(store, mode, fn) {
    return new Promise((resolve, reject) => {
      try {
        const tx = this.tx(store, mode);
        const os = tx.objectStore(store);
        const request = fn(os);
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
      } catch (e) { reject(e); }
    });
  },
// --- NEW OPTIMIZED CODE (paste this over the original code) ---

    _isUserData(store) {
        return (CONFIG.USER_DATA_STORES || []).indexOf(store) !== -1;
    },

    async _bumpBackupCounter() {
        try {
        const meta = (await this.getSetting('backupMeta', null)) || {
            lastBackupAt: null, changesSinceBackup: 0
        };
        meta.changesSinceBackup = (meta.changesSinceBackup || 0) + 1;
        await this.setSetting('backupMeta', meta);
        State.backupMeta = meta;
        } catch (e) { /* non-critical */ }
    },

    add(store, obj) {
        const v = WRITE_VALIDATORS[store];
        if (v) v(obj);
        this._invalidate();
        if (!obj.id) obj.id = Utils.uid();
          // Auto-stamp modification time on user-data stores so the merge engine
          // can tell which copy of a record is newer. Callers can override by
          // setting obj.updatedAt themselves before calling put()/add().
        if (this._isUserData(store) && !obj.updatedAt) {
          obj.updatedAt = new Date().toISOString();
        }
        const p = this.req(store, 'readwrite', os => os.add(obj));
        p.then(() => { if (this._isUserData(store)) this._bumpBackupCounter(); }).catch(() => {});
        return p;
    },
      put(store, obj) {
        const v = WRITE_VALIDATORS[store];
        if (v) v(obj);
        this._invalidate();
        if (!obj.id) obj.id = Utils.uid();  
        if (this._isUserData(store) && !obj.updatedAt) {
          obj.updatedAt = new Date().toISOString();
        }        
        const p = this.req(store, 'readwrite', os => os.put(obj));
        p.then(() => { if (this._isUserData(store)) this._bumpBackupCounter(); }).catch(() => {});
        return p;
    },
    get(store, id)     { return this.req(store, 'readonly', os => os.get(id)); },
    delete(store, id)  {
        this._invalidate();
        const p = this.req(store, 'readwrite', os => os.delete(id));
        p.then(() => { if (this._isUserData(store)) this._bumpBackupCounter(); }).catch(() => {});
        return p;
    },
    clear(store)       { this._invalidate(); return this.req(store, 'readwrite', os => os.clear()); },

    async getAll(store) {
        const cache = this._activeCache();
        if (cache) {
        const k = 'getAll|' + store;
        if (cache.has(k)) return cache.get(k);
        const v = await this.req(store, 'readonly', os => os.getAll());
        cache.set(k, v);
        return v;
        }
        return this.req(store, 'readonly', os => os.getAll());
    },

  async getAllByIndex(store, indexName, value) {
    const run = () => new Promise((resolve, reject) => {
      try {
        const tx = this.tx(store, 'readonly');
        const idx = tx.objectStore(store).index(indexName);
        const req = idx.getAll(value);
        req.onsuccess = () => resolve(req.result);
        req.onerror = () => reject(req.error);
      } catch (e) { reject(e); }
    });

    const cache = this._activeCache();
    if (cache) {
      const k = 'getAllByIndex|' + store + '|' + indexName + '|' + JSON.stringify(value);
      if (cache.has(k)) return cache.get(k);
      const v = await run();
      cache.set(k, v);
      return v;
    }
    return run();
  },

  async getSetting(key, def = null) {
    const cache = this._activeCache();
    if (cache) {
      const k = 'getSetting|' + key;
      if (cache.has(k)) return cache.get(k);
      const s = await this.get('settings', key);
      const v = s ? s.value : def;
      cache.set(k, v);
      return v;
    }
    const s = await this.get('settings', key);
    return s ? s.value : def;
  },

  async setSetting(key, value) { this._invalidate(); return this.put('settings', { id: key, value }); },
  async deleteSetting(key)     { this._invalidate(); return this.delete('settings', key); },
  async healthCheck() {
    try { await this.open(); await this.getAll('settings'); return true; }
    catch (e) { return false; }
  },
    /* ─────────────────────────────────────────────────────────────
     PERSISTENT STORAGE
     Browsers treat IndexedDB as "best-effort" by default and may
     silently evict the entire database under disk pressure or after
     a period of inactivity (Safari: 7 days). `persist()` asks the
     browser to mark this origin's storage as durable.
     ───────────────────────────────────────────────────────────── */
  async requestPersistentStorage() {
    if (!navigator.storage || !navigator.storage.persist) return null;
    try {
      const already = await navigator.storage.persisted();
      if (already) return { granted: true, already: true };
      const granted = await navigator.storage.persist();
      return { granted, already: false };
    } catch (e) {
      return { granted: false, error: e.message };
    }
  },

  async estimateUsage() {
    if (!navigator.storage || !navigator.storage.estimate) return null;
    try { return await navigator.storage.estimate(); } catch (e) { return null; }
  },
  async restoreSnapshot(snapshot, options = {}) {
    const replace = options.replace !== false;
    const stores = CONFIG.STORES.slice();
    const data = snapshot && snapshot.data;
    if (!data || typeof data !== 'object') throw new Error('Invalid backup data.');

    // ── Backward-compatible normalization ──────────────────────────────
    // A backup created by an older KlazAssist build will not contain every
    // store that exists in the current CONFIG.STORES (e.g. `rubrics` was
    // added in v1.1.0). We treat missing stores as empty arrays so that
    // valid old backups still restore cleanly, instead of failing with a
    // hard "Backup is incomplete" error.
    //
    // The integrity guarantees are preserved for stores that DO exist:
    //   • the payload must be an array
    //   • every record must be an object with a non-empty `id`
    const normalized = {};
    const missingStores = [];

    for (const store of stores) {
      const arr = data[store];

      if (arr === undefined || arr === null) {
        normalized[store] = [];
        missingStores.push(store);
        continue;
      }
      if (!Array.isArray(arr)) {
        throw new Error(`Invalid backup data for "${store}" — expected an array.`);
      }
      for (const item of arr) {
        if (!item || typeof item !== 'object' || item.id === undefined || item.id === null || item.id === '') {
          throw new Error(`Invalid record found in "${store}".`);
        }
      }
      normalized[store] = arr;
    }

    if (missingStores.length) {
      console.info(
        '[DB] Restoring a backup that predates these stores; they will be created empty:',
        missingStores.join(', ')
      );
    }
    // ───────────────────────────────────────────────────────────────────

    await this.open();
    this._invalidate();

    return new Promise((resolve, reject) => {
      let tx;
      try {
        tx = this.db.transaction(stores, 'readwrite');
      } catch (e) {
        reject(e);
        return;
      }

      let written = 0;
      let failed = null;

      tx.oncomplete = () => {
        this._invalidate();
        resolve(written);
      };
      tx.onerror = () => {
        failed = tx.error || new Error('Restore transaction failed.');
      };
      tx.onabort = () => {
        this._invalidate();
        reject(failed || tx.error || new Error('Restore was aborted. No changes were applied.'));
      };

      try {
        for (const store of stores) {
          const os = tx.objectStore(store);
          // A true restore reproduces the backup instead of silently merging
          // stale records that are no longer present in the backup.
          if (replace) os.clear();
          for (const item of normalized[store]) {   // ← was: data[store]
            os.put(item);
            written++;
          }
        }
      } catch (e) {
        failed = e;
        try { tx.abort(); } catch (_) {}
      }
    });
  },
    /* ─────────────────────────────────────────────────────────────
     ORPHAN CLEANUP
     Removes records whose foreign key (classId / learnerId /
     assessmentId) no longer points at an existing row. Runs on
     startup when the "cleanupDone" flag is not yet set.
     ───────────────────────────────────────────────────────────── */
  async cleanupOrphans() {
    const classIds      = new Set((await this.getAll('classes')).map(c => c.id));
    const learnerIds    = new Set((await this.getAll('learners')).map(l => l.id));
    const assessmentIds = new Set((await this.getAll('assessments')).map(a => a.id));

    const rules = [
      { store: 'learners',           test: r => r.classId && !classIds.has(r.classId) },
      { store: 'attendance',         test: r => r.learnerId && !learnerIds.has(r.learnerId) },
      { store: 'assessmentResults',  test: r => (r.learnerId && !learnerIds.has(r.learnerId)) ||
                                                (r.assessmentId && !assessmentIds.has(r.assessmentId)) },
      { store: 'termGrades',         test: r => r.learnerId && !learnerIds.has(r.learnerId) },
      { store: 'sf9Records',         test: r => r.learnerId && !learnerIds.has(r.learnerId) },
      { store: 'behaviorLogs',       test: r => r.learnerId && !learnerIds.has(r.learnerId) },
      { store: 'parentLogs',         test: r => r.learnerId && !learnerIds.has(r.learnerId) },
      { store: 'grades',             test: r => r.learnerId && !learnerIds.has(r.learnerId) }
    ];

    let removed = 0;
    const details = {};

    for (const rule of rules) {
      let rows;
      try { rows = await this.getAll(rule.store); }
      catch (e) { continue; }

      let count = 0;
      for (const r of rows) {
        if (!rule.test(r)) continue;
        try { await this.delete(rule.store, r.id); count++; }
        catch (e) { /* row may already be gone — keep going */ }
      }
      if (count) { details[rule.store] = count; removed += count; }
    }

    this._invalidate();
    return { removed, details };
  },

  /**
   * Atomic bulk write. All records succeed or none do.
   * mode = 'put' | 'delete'
   * For 'delete', pass an array of ids or objects with .id
   * Returns the number of records written.
   */
  async bulkWrite(store, records, mode = 'put') {
    if (!Array.isArray(records) || records.length === 0) return 0;
    await this.open();
    this._invalidate();
    return new Promise((resolve, reject) => {
      let tx;
      try {
        tx = this.db.transaction([store], 'readwrite');
      } catch (e) {
        reject(e);
        return;
      }
      const os = tx.objectStore(store);
      let count = 0;
      tx.oncomplete = () => {
        if (this._isUserData(store)) this._bumpBackupCounter();
        resolve(count);
      };
      tx.onerror = () => reject(tx.error || new Error('Bulk write failed.'));
      tx.onabort = () => reject(tx.error || new Error('Bulk write aborted.'));
      try {
        for (const rec of records) {
          if (mode === 'put') {
            if (!rec.id) rec.id = Utils.uid();
            os.put(rec);
          } else if (mode === 'delete') {
            os.delete(rec && rec.id !== undefined ? rec.id : rec);
          }
          count++;
        }
      } catch (e) {
        try { tx.abort(); } catch (_) {}
        reject(e);
      }
    });
  },

  async reset() {
    try {
      if (this.db) this.db.close();
      this.db = null; this.initPromise = null;
      await new Promise((resolve, reject) => {
        const req = indexedDB.deleteDatabase(CONFIG.DB_NAME);
        req.onsuccess = () => resolve();
        req.onerror = () => reject(req.error);
        req.onblocked = () => resolve();
      });
      return true;
    } catch (e) { return false; }
  }
};

/* ============================================================================
   AUTH
   ============================================================================ */
const Auth = {
  _account: null,
    /* ─────────────────────────────────────────────────────────────
     SHADOW BACKUP — mirror the account record into localStorage so
     that even if IDB gets evicted or overwritten, we can detect the
     change and offer to recover.
     ───────────────────────────────────────────────────────────── */
  SHADOW_KEY: 'klazassist.auth.shadow.v1',

  _writeShadow(account) {
    try {
      if (!account || !account.username) return;
      localStorage.setItem(this.SHADOW_KEY, JSON.stringify({
        username: account.username,
        usernameDisplay: account.usernameDisplay,
        password: account.password,
        recoveryHash: account.recoveryHash,
        recoveryCreatedAt: account.recoveryCreatedAt,
        createdAt: account.createdAt,
        savedAt: new Date().toISOString()
      }));
    } catch (e) { /* localStorage may be disabled — non-fatal */ }
  },

  _readShadow() {
    try {
      const raw = localStorage.getItem(this.SHADOW_KEY);
      if (!raw) return null;
      const parsed = JSON.parse(raw);
      if (!parsed || !parsed.username || !parsed.password) return null;
      return parsed;
    } catch (e) { return null; }
  },

  _clearShadow() {
    try { localStorage.removeItem(this.SHADOW_KEY); } catch (e) {}
  },
  ACCOUNT_KEY: 'auth.account',
  async load() {
    const rec = await DB.get('settings', this.ACCOUNT_KEY);
    this._account = rec ? rec.value : null;
    return this._account;
  },
  async exists() {
  if (!this._account) await this.load();
    return !!(
      this._account &&
      this._account.username &&
      this._account.password &&
      this._account.password.verifier
    );
  },

    /** If the stored hash was created with a higher iteration count than
      the current device target, quietly re-hash with the lower count.
      Runs AFTER a successful login, never blocks the user. */
  async maybeDowngradeHash(password) {
    try {
      const acc = this._account;
      if (!acc || !acc.password) return;
      const target = Security.adaptiveIterations();
      const current = acc.password.iterations || 0;
      if (current <= target) return;              // already optimal
      // Re-hash with the lower count
      const pw = await Security.hashPassword(password);
      await this.updateAccount({ password: pw });
      console.log(`[Auth] Hash downgraded ${current} → ${pw.iterations}`);
    } catch (e) {
      console.warn('[Auth] Hash downgrade skipped:', e);
    }
  },

  async createAccount({ name, username, password }) {
    const usernameNorm = String(username || '').trim().toLowerCase();
    if (!usernameNorm) throw new Error('Username is required');
    if (!Security.meetsMinimum(password)) throw new Error('Password does not meet minimum requirements');
    const pw = await Security.hashPassword(password);
    const now = new Date().toISOString();
    const account = {
      id: 'account',
      name: String(name || '').trim() || usernameNorm,
      username: usernameNorm,
      usernameDisplay: String(username || '').trim(),
      password: pw,
      recoveryHash: null,
      recoveryCreatedAt: null,
      createdAt: now,
      lastLoginAt: null,
      lastFailedLoginAt: null,
      failedAttempts: 0,
      lockedUntil: null,
      autoLockSec: CONFIG.IDLE_DEFAULT_SEC,
      rememberDevice: true
    };
    await DB.setSetting(this.ACCOUNT_KEY, account);
    this._account = account;
    this._writeShadow(account);  
    return account;
  },
  async updateAccount(patch) {
    if (!this._account) await this.load();
    const next = Object.assign({}, this._account, patch);
    await DB.setSetting(this.ACCOUNT_KEY, next);
    this._account = next;
    this._writeShadow(next);
    return next;
  },
  async setRecoveryKey(recoveryKey) {
    if (!this._account) await this.load();
    const hash = await Security.hashRecoveryKey(recoveryKey);
    await this.updateAccount({ recoveryHash: hash, recoveryCreatedAt: new Date().toISOString() });
  },
  async verifyRecoveryKey(recoveryKey) {
    if (!this._account || !this._account.recoveryHash) return false;
    const hash = await Security.hashRecoveryKey(recoveryKey);
    return Security.constantTimeEqual(hash, this._account.recoveryHash);
  },
  async verify(username, password) {
    if (!this._account) await this.load();
    if (!this._account) return { ok: false, reason: 'no-account' };
    const usernameNorm = String(username || '').trim().toLowerCase();
    const ok = await Security.verifyPassword(String(password || ''), this._account.password);
    const userMatch = usernameNorm && usernameNorm === String(this._account.username || '').toLowerCase();
    if (ok && userMatch) return { ok: true };
    return { ok: false, reason: 'invalid' };
  },
  async recordFailedAttempt() {
    if (!this._account) await this.load();
    if (!this._account) return;
    const failedAttempts = (this._account.failedAttempts || 0) + 1;
    const lastFailedLoginAt = new Date().toISOString();
    let lockedUntil = null;
    if (failedAttempts >= 10) lockedUntil = new Date(Date.now() + 5 * 60 * 1000).toISOString();
    else if (failedAttempts >= 8) lockedUntil = new Date(Date.now() + 60 * 1000).toISOString();
    await this.updateAccount({ failedAttempts, lastFailedLoginAt, lockedUntil });
  },
  async recordSuccessfulLogin() {
    if (!this._account) await this.load();
    if (!this._account) return;
    await this.updateAccount({
      lastLoginAt: new Date().toISOString(),
      failedAttempts: 0,
      lockedUntil: null
    });
  },
  isLocked() {
    if (!this._account || !this._account.lockedUntil) return null;
    const t = new Date(this._account.lockedUntil).getTime();
    if (isNaN(t)) return null;
    if (t <= Date.now()) return null;
    return Math.ceil((t - Date.now()) / 1000);
  },
  getProgressiveDelayMs() {
    const n = (this._account && this._account.failedAttempts) || 0;
    if (n < 3) return 0;
    if (n === 3) return 500;
    if (n === 4) return 1000;
    if (n === 5) return 2000;
    if (n === 6) return 3500;
    if (n === 7) return 5000;
    return 8000;
  },
  async changePassword(currentPw, newPw) {
    if (!this._account) await this.load();
    const ok = await Security.verifyPassword(currentPw, this._account.password);
    if (!ok) return { ok: false, reason: 'current' };
    if (!Security.meetsMinimum(newPw)) return { ok: false, reason: 'weak' };
    const pw = await Security.hashPassword(newPw);
    await this.updateAccount({ password: pw });
    return { ok: true };
  }
};

/* ============================================================================
   SESSION
   ============================================================================ */
const Session = {
  state: {
    authenticated: false,
    locked: false,
    createdAt: 0,
    lastActivity: 0,
    expiresAt: 0,
    remember: false,
    sessionId: null
  },
  _tickHandle: null,
  _warningShownFor: 0,
  STORAGE_KEY: 'klazassist.session.v1',

    /* ----------------------------------------------------------------
   Persist the current session state to localStorage.
   Only remembered sessions are saved — non-remembered sessions
   already require a fresh sign-in on reload, which is stricter.
   ---------------------------------------------------------------- */
_persist() {
  if (!this.state.remember || !this.state.expiresAt) return;
  try {
    localStorage.setItem(this.STORAGE_KEY, JSON.stringify({
      sessionId: this.state.sessionId,
      createdAt: this.state.createdAt,
      expiresAt: this.state.expiresAt,
      user: Auth._account ? Auth._account.username : null,
      locked: this.state.locked === true    // ← the new bit
    }));
  } catch (e) { /* localStorage disabled — session is memory-only this run */ }
},

  start({ remember }) {
    const now = Date.now();
    this.state.authenticated = true;
    this.state.locked = false;
    this.state.createdAt = now;
    this.state.lastActivity = now;
    this.state.remember = !!remember;
    this.state.sessionId = Utils.uid('sess-');
    if (remember) {
      this.state.expiresAt = now + CONFIG.SESSION_HOURS * 3600 * 1000;
    } else {
      this.state.expiresAt = 0;
      try { localStorage.removeItem(this.STORAGE_KEY); } catch (e) {}
    }
    this._persist();          // ← was inline localStorage.setItem
    this.startTicker();
    this.updateUI();
  },
  async tryResume() {
    let raw = null;
    try { raw = localStorage.getItem(this.STORAGE_KEY); } catch (e) {}
    if (!raw) return false;
    try {
      const s = JSON.parse(raw);
      if (!s || !s.expiresAt) return false;
      if (s.expiresAt <= Date.now()) {
        try { localStorage.removeItem(this.STORAGE_KEY); } catch (e) {}
        return false;
      }
      if (!Auth._account || Auth._account.username !== s.user) {
        try { localStorage.removeItem(this.STORAGE_KEY); } catch (e) {}
        return false;
      } 
      this.state.authenticated = true;
      this.state.locked = s.locked === true;    // ← was `false`
      this.state.createdAt = s.createdAt || Date.now();
      this.state.lastActivity = Date.now();
      this.state.expiresAt = s.expiresAt;
      this.state.remember = true;
      this.state.sessionId = s.sessionId || Utils.uid('sess-');
      this.startTicker();
      this.updateUI();
      return true;
    } catch (e) { return false; }
  },
  end() {
    this.state.authenticated = false;
    this.state.locked = false;
    this.state.createdAt = 0;
    this.state.lastActivity = 0;
    this.state.expiresAt = 0;
    this.state.sessionId = null;
    try { localStorage.removeItem(this.STORAGE_KEY); } catch (e) {}
    this.stopTicker();
    this.updateUI();
  },
  lock(reason) {
    if (!this.state.authenticated) return;
    this.state.locked = true;
    this._persist();
    AuthUI.showLock(reason);
    App.logActivity('Application locked' + (reason ? ' (' + reason + ')' : ''), 'Security');
    this.updateUI();
  },
  unlock() {
    this.state.locked = false;
    this._persist();
    this.touch();
    AuthUI.hideLock();
    this.updateUI();
  },
  touch() {
    if (!this.state.authenticated) return;
    this.state.lastActivity = Date.now();
    if (this.state.remember && this.state.expiresAt) {
      const now = Date.now();
      const remaining = this.state.expiresAt - now;
      const windowMs = CONFIG.SESSION_HOURS * 3600 * 1000;
      if (remaining < windowMs * 0.5) {
        this.state.expiresAt = now + windowMs;
        this._persist();
       }
    }
    this.updateUI();
  },
  idleLimitSec() {
    if (Auth._account && typeof Auth._account.autoLockSec === 'number') return Auth._account.autoLockSec;
    return CONFIG.IDLE_DEFAULT_SEC;
  },
  remainingIdleSec() {
    const limit = this.idleLimitSec();
    if (!limit) return Infinity;
    const used = (Date.now() - this.state.lastActivity) / 1000;
    return Math.max(0, limit - used);
  },
  remainingSessionSec() {
    if (!this.state.expiresAt) return Infinity;
    return Math.max(0, Math.floor((this.state.expiresAt - Date.now()) / 1000));
  },
  startTicker() {
    this.stopTicker();
    this._tickHandle = setInterval(() => this.tick(), 1000);
  },
  stopTicker() {
    if (this._tickHandle) { clearInterval(this._tickHandle); this._tickHandle = null; }
  },
  tick() {
    if (!this.state.authenticated) return;
    if (this.state.locked) return;
    if (this.state.expiresAt && Date.now() >= this.state.expiresAt) {
      this.end();
      UI.toast('Session expired. Please sign in again.', 'info');
      AuthUI.showLogin();
      App.logActivity('Session expired', 'Security');
      return;
    }
    const idleLimit = this.idleLimitSec();
    if (!idleLimit) { this.updateUI(); return; }
    const idle = (Date.now() - this.state.lastActivity) / 1000;
    const remaining = idleLimit - idle;
    if (remaining <= CONFIG.SESSION_WARNING_SEC && remaining > 0) {
      if (this._warningShownFor !== Math.floor(remaining / 5)) {
        this._warningShownFor = Math.floor(remaining / 5);
        AuthUI.showSessionWarning(Math.ceil(remaining));
      }
    } else if (remaining > CONFIG.SESSION_WARNING_SEC) {
      AuthUI.hideSessionWarning();
    }
    if (idle >= idleLimit) {
      AuthUI.hideSessionWarning();
      this.lock('inactivity');
      return;
    }
    this.updateUI();
  },
  updateUI() {
    const pill = document.getElementById('security-pill');
    const text = document.getElementById('security-pill-text');
    if (!pill || !text) return;
    pill.classList.remove('warn', 'danger');
    if (!this.state.authenticated) { text.textContent = 'Signed out'; pill.classList.add('danger'); return; }
    if (this.state.locked) { text.textContent = 'Locked'; pill.classList.add('danger'); return; }
    const idleRem = this.remainingIdleSec();
    const sessRem = this.remainingSessionSec();
    const rem = Math.min(idleRem, sessRem);
    if (!isFinite(rem)) { text.textContent = 'Protected'; return; }
    if (rem < 60) { text.textContent = 'Auto-lock <1m'; pill.classList.add('danger'); }
    else if (rem < 300) { text.textContent = 'Auto-lock ' + Math.ceil(rem/60) + 'm'; pill.classList.add('warn'); }
    else if (rem < 3600) { text.textContent = 'Auto-lock ' + Math.ceil(rem/60) + 'm'; }
    else { text.textContent = 'Protected'; }
  }
};

/* ============================================================================
   UI
   ============================================================================ */
const UI = {
  toast(msg, type = 'info', duration = 3500) {
    const container = document.getElementById('toast-container');
    const icons = {
      success: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M20 6L9 17l-5-5"/></svg>',
      error: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><path d="M15 9l-6 6M9 9l6 6"/></svg>',
      warning: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/><path d="M12 9v4M12 17h.01"/></svg>',
      info: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><path d="M12 16v-4M12 8h.01"/></svg>'
    };
    const el = document.createElement('div');
    el.className = 'toast ' + type;
    el.setAttribute('role', 'status');
    el.innerHTML = `<span class="toast-icon">${icons[type] || icons.info}</span><span class="toast-msg">${Utils.esc(msg)}</span><button class="toast-close" aria-label="Dismiss">&times;</button>`;
    el.querySelector('.toast-close').onclick = () => el.remove();
    container.appendChild(el);
    setTimeout(() => { el.style.opacity = '0'; el.style.transform = 'translateX(20px)'; setTimeout(()=>el.remove(), 250); }, duration);
  },
  modal({ title, body, footer, size = '', onClose, onOpen }) {
    const root = document.getElementById('modal-root');
    const overlay = document.createElement('div');
    overlay.className = 'modal-overlay show';
    overlay.setAttribute('role', 'dialog');
    overlay.setAttribute('aria-modal', 'true');
    const id = Utils.uid('modal-');
    overlay.innerHTML = `
      <div class="modal ${size}" role="document">
        <div class="modal-head">
          <h3 id="${id}-title">${Utils.esc(title || '')}</h3>
          <button class="icon-btn" aria-label="Close" data-close>
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 6L6 18M6 6l12 12"/></svg>
          </button>
        </div>
        <div class="modal-body" id="${id}-body"></div>
        ${footer !== false ? `<div class="modal-foot" id="${id}-foot">${footer || ''}</div>` : ''}
      </div>`;
    const bodyEl = overlay.querySelector(`#${id}-body`);
    if (typeof body === 'string') bodyEl.innerHTML = body;
    else if (body instanceof HTMLElement) bodyEl.appendChild(body);
    root.appendChild(overlay);
    overlay.setAttribute('aria-labelledby', `${id}-title`);
    const close = () => {
      overlay.classList.remove('show');
      setTimeout(() => overlay.remove(), 150);
      document.removeEventListener('keydown', escHandler);
      if (onClose) onClose();
    };
    const escHandler = (e) => { if (e.key === 'Escape') close(); };
    document.addEventListener('keydown', escHandler);
    overlay.querySelectorAll('[data-close]').forEach(b => b.onclick = close);
    overlay.addEventListener('mousedown', (e) => { if (e.target === overlay) close(); });
    setTimeout(() => {
      const first = overlay.querySelector('input:not([type=file]), select, textarea, button:not([data-close])');
      if (first) first.focus();
      if (onOpen) onOpen(overlay, close);
    }, 50);
    return { overlay, close, body: bodyEl };
  },
  confirm({ title = 'Confirm', message, confirmText = 'Confirm', confirmClass = 'btn-danger', onConfirm }) {
    const m = this.modal({
      title,
      body: `<p style="font-size:14px;line-height:1.6;">${message}</p>`,
      footer: `<button class="btn btn-outline" data-cancel>Cancel</button>
               <button class="btn ${confirmClass}" data-confirm>${Utils.esc(confirmText)}</button>`
    });
    m.overlay.querySelector('[data-cancel]').onclick = m.close;
    m.overlay.querySelector('[data-confirm]').onclick = () => { m.close(); if (onConfirm) onConfirm(); };
    return m;
  },
  prompt({ title, message, placeholder = '', value = '', confirmText = 'OK', onConfirm }) {
    const m = this.modal({
      title,
      body: `<p style="margin-bottom:10px;font-size:13px;color:var(--text-muted);">${message || ''}</p>
             <input class="form-control" id="prompt-input" placeholder="${Utils.attr(placeholder)}" value="${Utils.attr(value)}">`,
      footer: `<button class="btn btn-outline" data-cancel>Cancel</button>
               <button class="btn btn-primary" data-confirm>${Utils.esc(confirmText)}</button>`
    });
    const input = m.overlay.querySelector('#prompt-input');
    m.overlay.querySelector('[data-cancel]').onclick = m.close;
    m.overlay.querySelector('[data-confirm]').onclick = () => {
      const v = input.value.trim(); m.close(); if (onConfirm) onConfirm(v);
    };
    input.addEventListener('keydown', (e) => { if (e.key === 'Enter') m.overlay.querySelector('[data-confirm]').click(); });
    return m;
  },
  emptyState({ icon = 'inbox', title, message, actionLabel, actionFn }) {
    const icons = {
      inbox: '<path d="M22 12h-6l-2 3h-4l-2-3H2M5.45 5.11L2 12v6a2 2 0 002 2h16a2 2 0 002-2v-6l-3.45-6.89A2 2 0 0016.76 4H7.24a2 2 0 00-1.79 1.11z"/>',
      users: '<path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2M9 7a4 4 0 100 8 4 4 0 000-8zM23 21v-2a4 4 0 00-3-3.87M16 3.13a4 4 0 010 7.75"/>',
      calendar: '<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/>',
      file: '<path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><path d="M14 2v6h6"/>',
      trash: '<path d="M3 6h18"/><path d="M19 6v14a2 2 0 01-2 2H7a2 2 0 01-2-2V6"/><path d="M8 6V4a2 2 0 012-2h4a2 2 0 012 2v2"/><line x1="10" y1="11" x2="10" y2="17"/><line x1="14" y1="11" x2="14" y2="17"/>',
      
      chart: '<path d="M12 20V10M18 20V4M6 20v-4"/>',
      search: '<circle cx="11" cy="11" r="8"/><path d="M21 21l-4.35-4.35"/>'
    };
    const fnAttr = actionFn ? Utils.attr(actionFn) : '';
    return `<div class="empty-state">
      <div class="empty-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">${icons[icon] || icons.inbox}</svg></div>
      <h3>${Utils.esc(title)}</h3>
      <p>${Utils.esc(message)}</p>
      ${actionLabel ? `<button class="btn btn-primary" onclick="${fnAttr}">${Utils.esc(actionLabel)}</button>` : ''}
    </div>`;
  },
  pagination(total, page, pageSize, onPage) {
    const totalPages = Math.max(1, Math.ceil(total / pageSize));
    if (totalPages <= 1) return '';
    let html = '<div class="pagination">';
    html += `<button ${page <= 1 ? 'disabled' : ''} data-page="${page-1}">&laquo;</button>`;
    const start = Math.max(1, page - 2);
    const end = Math.min(totalPages, page + 2);
    if (start > 1) html += `<button data-page="1">1</button>`;
    if (start > 2) html += `<span style="padding:0 4px;color:var(--text-muted);">…</span>`;
    for (let i = start; i <= end; i++) html += `<button class="${i === page ? 'active' : ''}" data-page="${i}">${i}</button>`;
    if (end < totalPages - 1) html += `<span style="padding:0 4px;color:var(--text-muted);">…</span>`;
    if (end < totalPages) html += `<button data-page="${totalPages}">${totalPages}</button>`;
    html += `<button ${page >= totalPages ? 'disabled' : ''} data-page="${page+1}">&raquo;</button>`;
    html += '</div>';
    setTimeout(() => {
      document.querySelectorAll('.pagination button[data-page]').forEach(b => {
        b.onclick = () => onPage(Number(b.dataset.page));
      });
    }, 0);
    return html;
  },
  loadingSkeleton(rows = 5) {
    let h = '';
    for (let i = 0; i < rows; i++) {
      h += `<div style="display:flex;gap:12px;align-items:center;padding:12px 0;border-bottom:1px solid var(--border);">
        <div class="skeleton" style="width:36px;height:36px;border-radius:50%;"></div>
        <div style="flex:1;">
          <div class="skeleton" style="height:12px;width:60%;margin-bottom:6px;"></div>
          <div class="skeleton" style="height:10px;width:40%;"></div>
        </div>
      </div>`;
    }
    return h;
  },
  statusBadge(status) {
    const map = {
      'active': 'badge-success', 'present': 'badge-success',
      'inactive': 'badge-neutral', 'absent': 'badge-danger',
      'transferred': 'badge-warning', 'late': 'badge-warning',
      'dropped': 'badge-danger', 'excused': 'badge-blue',
      'graduated': 'badge-blue', 'assigned': 'badge-blue',
      'submitted': 'badge-success', 'missing': 'badge-danger',
      'completed': 'badge-success'
    };
    return `<span class="badge ${map[(status||'').toLowerCase()] || 'badge-neutral'}">${Utils.esc(status || '—')}</span>`;
  },
  barChart(data, { height = 200, color = 'var(--deped-blue)', showValues = true } = {}) {
    if (!data.length) return '<div class="empty-state" style="padding:20px;"><p class="text-muted">No data available</p></div>';
    const max = Math.max(...data.map(d => d.value), 1);
    const barW = 100 / data.length;
    let svg = `<svg class="chart" viewBox="0 0 400 ${height}" preserveAspectRatio="none" style="height:${height}px;">`;
    for (let i = 0; i <= 4; i++) {
      const y = 20 + (height - 50) * i / 4;
      svg += `<line x1="0" y1="${y}" x2="400" y2="${y}" stroke="var(--border)" stroke-width="0.5" stroke-dasharray="3 3"/>`;
    }
    data.forEach((d, i) => {
      const h = (d.value / max) * (height - 50);
      const x = i * barW * 4 + barW * 0.8;
      const w = barW * 4 * 0.6;
      const y = height - 30 - h;
      svg += `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="3" fill="${d.color || color}" opacity="0.9"><title>${Utils.esc(d.label)}: ${d.value}</title></rect>`;
      if (showValues) svg += `<text x="${x + w/2}" y="${y - 4}" text-anchor="middle" font-size="10" fill="var(--text-muted)" font-weight="600">${d.value}</text>`;
      svg += `<text x="${x + w/2}" y="${height - 12}" text-anchor="middle" font-size="9" fill="var(--text-muted)">${Utils.esc(d.label)}</text>`;
    });
    svg += '</svg>';
    return svg;
  },
  donutChart(data, { size = 160, thickness = 24 } = {}) {
    const total = data.reduce((s, d) => s + d.value, 0) || 1;
    const r = (size - thickness) / 2;
    const cx = size / 2, cy = size / 2;
    const circ = 2 * Math.PI * r;
    let offset = 0;
    let svg = `<svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">`;
    svg += `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="var(--border)" stroke-width="${thickness}"/>`;
    data.forEach(d => {
      const len = (d.value / total) * circ;
      svg += `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${d.color}" stroke-width="${thickness}"
        stroke-dasharray="${len} ${circ - len}" stroke-dashoffset="${-offset}" transform="rotate(-90 ${cx} ${cy})"><title>${Utils.esc(d.label)}: ${d.value}</title></circle>`;
      offset += len;
    });
    svg += `<text x="${cx}" y="${cy - 4}" text-anchor="middle" font-size="22" font-weight="800" fill="var(--text)">${total}</text>`;
    svg += `<text x="${cx}" y="${cy + 16}" text-anchor="middle" font-size="10" fill="var(--text-muted)">Total</text>`;
    svg += '</svg>';
    return svg;
  }


};

/* ============================================================================
   SHARE — email + Web Share API
   ----------------------------------------------------------------------------
   KlazAssist cannot send SMTP directly. This module builds a well-formed
   message, then hands it off to the user's email client via 'mailto:', or
   to the native OS share sheet via the Web Share API (mobile only).

   No credentials, no server, no third-party dependency.
   ============================================================================ */
const Share = {
  /** Compose a mailto: URL with proper encoding. */
  buildMailto({ to = '', cc = '', bcc = '', subject = '', body = '' } = {}) {
    const recipients = [to, cc ? 'cc=' + encodeURIComponent(cc) : '', bcc ? 'bcc=' + encodeURIComponent(bcc) : '']
      .filter(Boolean).join(',').replace(/^,/, '');
    const params = new URLSearchParams();
    if (subject) params.set('subject', subject);
    if (body)    params.set('body', body);
    const qs = params.toString();
    return `mailto:${recipients}${qs ? '?' + qs : ''}`;
  },

  /** Open the user's default mail client with the message pre-filled.
      The mailto: is dispatched via a hidden anchor with target="_blank",
      so the browser hands off to the OS protocol handler (Gmail, Outlook,
      Mail.app, etc.) WITHOUT navigating the current KlazAssist tab. */
  openMail({ to, cc, bcc, subject, body }) {
    const url = this.buildMailto({ to, cc, bcc, subject, body });

    // Very long mailto URLs can be rejected by some clients — cap the body
    // at a sane length and warn the user if we trim.
    if (url.length > 1900) {
      UI.toast('Message is very long — some mail apps may truncate it.', 'warning', 5000);
    }

    // Create a hidden anchor and click it. The combination of target="_blank"
    // plus rel="noopener noreferrer" tells the browser:
    //   • open in a NEW context, not this tab
    //   • don't hand the new context a reference to window.opener
    //   • don't leak the referrer
    const a = document.createElement('a');
    a.href = url;
    a.target = '_blank';
    a.rel = 'noopener noreferrer';
    a.style.display = 'none';
    document.body.appendChild(a);
    try {
      a.click();
    } finally {
      // Clean up the anchor on the next frame so the click has definitely fired.
      setTimeout(() => { try { a.remove(); } catch (e) {} }, 0);
    }
  },

  /** Native share sheet (mobile). Returns true if the share succeeded. */
  async nativeShare({ title, text, files }) {
    if (!navigator.share) return false;
    try {
      const payload = { title, text };
      if (files && files.length && navigator.canShare && navigator.canShare({ files })) {
        payload.files = files;
      }
      await navigator.share(payload);
      return true;
    } catch (e) {
      if (e && e.name === 'AbortError') return true; // user cancelled — not an error
      return false;
    }
  },

  /** Sign-off line built from the teacher + school profiles. */
  _signature() {
    const t = State.currentUser || {};
    const s = State.schools[0] || {};
    const parts = [];
    if (t.fullName)  parts.push(t.fullName);
    if (t.position)  parts.push(t.position);
    if (s.name)      parts.push(s.name);
    if (s.division)  parts.push(s.division);
    if (t.contact)   parts.push(t.contact);
    if (t.email)     parts.push(t.email);
    return parts.join('\n') + '\n\n— Sent from KlazAssist';
  },

  /* -----------------------------------------------------------------------
     High-level senders — one per report type
     ----------------------------------------------------------------------- */

  /** Share a learner's SF9 report card summary by email. */
  emailLearnerReport(learner, extra = {}) {
    if (!learner) return;
    const cls = State.activeClass || {};
    const teacher = State.currentUser || {};
    const parentEmail = extra.to || learner.learnerEmail || '';
    const subject = `Progress Report — ${Utils.fullName(learner)} (${cls.gradeLevel || ''} - ${cls.section || ''})`;
    const body =
`Dear Parent/Guardian of ${learner.firstName || Utils.fullName(learner)},

I hope this message finds you well. Please find below a summary of ${learner.firstName || 'your child'}'s progress this term.

${extra.summary || '(Grade and attendance summary will be provided in a follow-up message.)'}

If you have any questions or would like to discuss this further, please feel free to reach out.

Thank you for your continued partnership.

${this._signature()}`;

    const recipients = [parentEmail].filter(Boolean).join(',');
    if (!recipients) {
      // No email on file — prompt the teacher to type one
      UI.prompt({
        title: 'Send Progress Report',
        message: `No email address is on file for ${Utils.fullName(learner)}. Enter the parent's email to continue, or cancel.`,
        placeholder: 'parent@example.com',
        confirmText: 'Compose',
        onConfirm: (val) => {
          if (!val || !Utils.esc(val).match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/)) {
            UI.toast('That does not look like a valid email address.', 'warning');
            return;
          }
          this.sendSmart({ to: val.trim(), subject, body });
        }
      });
      return;
    }
    this.sendSmart({ to: recipients, subject, body });
  },

  /** Share a Class Profile summary with the school head or division office. */
  emailClassSummary({ to = '', extraNote = '' } = {}) {
    const cls = State.activeClass;
    if (!cls) { UI.toast('No class selected.', 'warning'); return; }
    const s = State.schools[0] || {};
    const teacher = State.currentUser || {};
    const total = State.learners.length;
    const sexes = { Male: 0, Female: 0, Other: 0 };
    State.learners.forEach(l => {
      const n = Utils.normalizeSex(l.sex);
      if (n === 'Male') sexes.Male++;
      else if (n === 'Female') sexes.Female++;
      else sexes.Other++;
    });

    const subject = `Class Summary — ${cls.gradeLevel} ${cls.section} (SY ${cls.schoolYear || State.schoolYear})`;
    const body =
`Dear ${s.schoolHead || 'Sir/Madam'},

Attached is a summary of my advisory class for this term.

Class:        ${cls.gradeLevel} - ${cls.section}
Subject:      ${cls.subject || '—'}
School Year:  ${cls.schoolYear || State.schoolYear}
Adviser:      ${cls.adviser || teacher.fullName || '—'}

Learners:     ${total}
              ${sexes.Male} Male · ${sexes.Female} Female${sexes.Other ? ' · ' + sexes.Other + ' unrecorded' : ''}

${extraNote ? extraNote + '\n\n' : ''}Please let me know if you need any additional information or supporting documents.

${this._signature()}`;

    const recipients = to || s.email || '';
    if (!recipients) {
      UI.prompt({
        title: 'Email Class Summary',
        message: 'Enter the recipient\'s email address. This will open your default mail app.',
        placeholder: 'schoolhead@deped.gov.ph',
        confirmText: 'Compose',
        onConfirm: (val) => {
          const v = (val || '').trim();
          if (!v || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)) {
            UI.toast('Please enter a valid email address.', 'warning');
            return;
          }
          this.sendSmart({ to: v, subject, body });
        }
      });
      return;
    }
    this.sendSmart({ to: recipients, subject, body });
  },

  /** Share the general "please review my records" note. */
  emailBackupReminder({ to = '' } = {}) {
    const teacher = State.currentUser || {};
    const subject = `KlazAssist Records — Backup Confirmation`;
    const body =
`Hi${teacher.fullName ? ' ' + teacher.fullName.split(' ')[0] : ''},

Just a quick note to confirm that my classroom records are backed up and up to date as of ${new Date().toLocaleDateString('en-PH', { month: 'long', day: 'numeric', year: 'numeric' })}.

${this._signature()}`;
    return this.sendSmart({ to, subject, body });
  },

  /* ---------------------------------------------------------------------
     Background send via Web3Forms
     --------------------------------------------------------------------- */

  /** Returns true if a Web3Forms access key is stored and looks plausibly
      valid (i.e. long enough to be a real key, not an empty string). */
  async hasBackgroundEmail() {
    try {
      const key = await DB.getSetting('web3formsKey', '');
      return !!(key && String(key).trim().length >= 20);
    } catch (e) {
      return false;
    }
  },

  /** POST the composed message to Web3Forms.
      Returns { ok: true, data } on success, or { ok: false, error } on any
      failure so the caller can decide whether to fall back to mailto:. */
  async sendViaWeb3Forms({ to = '', subject = '', body = '', from = '', replyto = '' } = {}) {
    let key = '';
    try { key = (await DB.getSetting('web3formsKey', '')) || ''; } catch (e) {}
    key = String(key).trim();
    if (!key) return { ok: false, error: 'No Web3Forms access key is configured.' };

    const school  = State.schools[0] || {};
    const teacher = State.currentUser || {};

    // Web3Forms accepts: access_key, subject, from_name, email, message.
    // `email` becomes the Reply-To header on the outgoing mail. The free
    // tier delivers to the address registered to the access key; the `to`
    // field is not universally honoured, so we include the intended
    // recipient in the body as a safety net.
    const intended = to ? `Intended recipient: ${to}\n\n` : '';
    const payload = {
      access_key: key,
      subject:    subject || 'KlazAssist message',
      from_name:  from || school.name || 'KlazAssist',
      email:      replyto || teacher.email || school.email || 'noreply@klazassist.local',
      message:    intended + (body || '')
    };
    if (to) payload.to = to;

    try {
      const res = await fetch('https://api.web3forms.com/submit', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
        body: JSON.stringify(payload)
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || data.success === false) {
        return { ok: false, error: (data && data.message) || ('HTTP ' + res.status) };
      }
      return { ok: true, data };
    } catch (e) {
      return { ok: false, error: e.message || 'Network error' };
    }
  },

  /* ---------------------------------------------------------------------
     Send-method preference + unified send path
     --------------------------------------------------------------------- */

  /** Returns 'web3forms' or 'native'. Defaults to 'native'. */
  async getSendMethod() {
    try {
      const m = await DB.getSetting('emailSendMethod', 'native');
      return (m === 'web3forms') ? 'web3forms' : 'native';
    } catch (e) {
      return 'native';
    }
  },

  async setSendMethod(method) {
    const m = (method === 'web3forms') ? 'web3forms' : 'native';
    await DB.setSetting('emailSendMethod', m);
    return m;
  },

  /** Native path: mobile share sheet, then mailto:.
      The Web Share API is only used on real mobile platforms — on desktop
      Windows/macOS/Linux it routes to the "Share" system panel (Copilot,
      Microsoft 365, etc.) which has no email client, so we skip it there
      and go straight to mailto:. */
  async _sendNative({ to = '', subject = '', body = '' } = {}) {
    const isMobile = this._isMobilePlatform();

    if (isMobile && typeof navigator !== 'undefined' && typeof navigator.share === 'function') {
      const shareText = to ? `To: ${to}\n\n${body}` : body;
      const shared = await this.nativeShare({ title: subject, text: shareText });
      if (shared) {
        App.logActivity('Email shared via share sheet' + (to ? ' — ' + to : ''), 'Email');
        return { ok: true, method: 'share' };
      }
      // User cancelled or the sheet failed — fall through to mailto.
    }

    this.openMail({ to, subject, body });
    App.logActivity('Email opened in mail app' + (to ? ' — ' + to : ''), 'Email');
    return { ok: true, method: 'mailto' };
  },

  /** True only on genuine touch-first mobile OSes. Windows tablets, macOS
      with touch bars, and Chromebooks are intentionally treated as desktop
      so they get the mailto: path. */
  _isMobilePlatform() {
    if (typeof navigator === 'undefined') return false;
    const ua = navigator.userAgent || '';
    // Android and iOS family. iPad on iOS 13+ reports as Mac, so we also
    // check for touch points.
    if (/Android|iPhone|iPad|iPod|Opera Mini|IEMobile|Mobile/i.test(ua)) return true;
    if (/Macintosh/.test(ua) && navigator.maxTouchPoints > 1) return true;
    return false;
  },

  /** Unified send used by every high-level sender.
      Respects the user's stored preference. On Web3Forms failure the
      message is re-routed to the native path so a click on "Email"
      always attempts delivery. */
  async sendSmart({ to = '', subject = '', body = '', from = '', replyto = '' } = {}) {
    const method = await this.getSendMethod();

    if (method === 'web3forms') {
      const configured = await this.hasBackgroundEmail();
      if (!configured) {
        UI.toast('Web3Forms is not configured — opening your mail app instead.', 'warning', 5500);
        return this._sendNative({ to, subject, body });
      }
      const result = await this.sendViaWeb3Forms({ to, subject, body, from, replyto });
      if (result.ok) {
        App.logActivity('Email sent via Web3Forms — ' + (to || '(default recipient)'), 'Email');
        return result;
      }
      console.warn('[Share] Web3Forms failed:', result.error);
      UI.toast('Web3Forms failed — opening your mail app instead.', 'warning', 6500);
    }

    return this._sendNative({ to, subject, body });
  },
};

