    const search = document.getElementById('learner-search');
    const status = document.getElementById('learner-filter-status');
    const sex    = document.getElementById('learner-filter-sex');
    if (search) State.learnersFilter.query  = search.value;
    if (status) State.learnersFilter.status = status.value;
    if (sex)    State.learnersFilter.sex    = sex.value;
    State.page.learners = 1;
    Pages._refreshLearnersTable();
